/* Recognition Studio.
 *
 * A static page. It reads artifacts a run already committed under data/ and
 * renders them; it never runs the pipeline and never holds a secret. The 3D
 * view draws mesh.json (triangulated when the artifact was produced, not here),
 * which is what lets a real model load with no backend at all.
 *
 * Three parts: the interview, the viewer, and the result panes.
 */
import * as THREE from "three";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/controls/OrbitControls.js";

const $ = (id) => document.getElementById(id);
const el = (tag, cls, text) => {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
};

const State = { brief: null, run: null, project: null, candidate: null };

/* ══════════════════════════════════════════════════════════════════════
   1 · The interview
   Five questions. Only the ones a tier:law rule genuinely needs are
   blocking; everything else gets a default that is shown as an assumption
   rather than hidden. The `why` on each question names the rule that asks
   for it, so nobody is answering a form they don't understand.
   ══════════════════════════════════════════════════════════════════════ */

const ROOMS = [
  { key: "living",   label: "Living room", def: 1 },
  { key: "kitchen",  label: "Kitchen",     def: 1 },
  { key: "bedroom",  label: "Bedrooms",    def: 2 },
  { key: "bathroom", label: "Bathroom",    def: 1 },
  { key: "office",   label: "Study",       def: 0 },
  { key: "utility",  label: "Utility",     def: 0 },
];

const QUESTIONS = [
  {
    id: "building_class", type: "single", q: "What are you building?",
    why: "Selects which rules apply.",
    options: [
      ["detached_house", "A detached house"],
      ["semi_detached", "A semi-detached house"],
      ["apartment_block", "An apartment building"],
    ],
    def: "detached_house",
  },
  {
    id: "dwelling_count", type: "number", q: "How many homes are in it?",
    why: "Required by <b>BayBO Art. 48 (1)</b> — above two, one storey must be barrier-free.",
    def: 1, min: 1, max: 24, unit: "homes", blocking: true,
  },
  {
    id: "rooms", type: "rooms", q: "Which rooms, and how many?",
    why: "The programme. A dwelling needs a kitchen and a bathroom — <b>BayBO Art. 46</b>.",
  },
  {
    id: "plot", type: "plot", q: "How big is the plot?",
    why: "Bounds the envelope. Leave it if you're not sure.",
    def: [18, 24],
  },
  {
    id: "notes", type: "text", q: "Anything else we should know?",
    why: "Free text — orientation, a view to keep, how you live in it.",
    placeholder: "e.g. living room facing the garden, south",
  },
];

function renderInterview() {
  const list = $("qlist");
  list.innerHTML = "";
  for (const q of QUESTIONS) {
    const li = el("li", "q");
    const head = el("div", "qh");
    head.append(el("span", "num"), Object.assign(el("label", "qt", q.q), { htmlFor: `f-${q.id}` }));
    li.append(head);
    const why = el("p", "why");
    why.innerHTML = q.why;
    li.append(why);
    li.append(fieldFor(q));
    list.append(li);
  }
  refreshAssumptions();
}

function fieldFor(q) {
  if (q.type === "single") {
    const wrap = el("div", "opts");
    q.options.forEach(([val, label]) => {
      const b = el("button", "opt", label);
      b.type = "button";
      b.setAttribute("aria-pressed", String(val === q.def));
      b.dataset.value = val;
      b.onclick = () => {
        [...wrap.children].forEach((c) => c.setAttribute("aria-pressed", "false"));
        b.setAttribute("aria-pressed", "true");
        q.value = val;
        refreshAssumptions();
      };
      wrap.append(b);
    });
    q.value = q.def;
    return wrap;
  }

  if (q.type === "number") {
    const wrap = el("div", "pair");
    const i = el("input");
    Object.assign(i, { type: "number", id: `f-${q.id}`, value: q.def, min: q.min, max: q.max });
    i.oninput = () => { q.value = Number(i.value) || q.def; refreshAssumptions(); };
    q.value = q.def;
    wrap.append(i, el("span", null, q.unit || ""));
    return wrap;
  }

  if (q.type === "rooms") {
    const grid = el("div", "rooms-grid");
    q.value = {};
    ROOMS.forEach((r) => {
      q.value[r.key] = r.def;
      const row = el("div", "room-row" + (r.def ? " on" : ""));
      const n = el("span", "n", String(r.def));
      const dec = el("button", null, "−"); dec.type = "button";
      const inc = el("button", null, "+"); inc.type = "button";
      const set = (v) => {
        q.value[r.key] = Math.max(0, Math.min(6, v));
        n.textContent = String(q.value[r.key]);
        row.classList.toggle("on", q.value[r.key] > 0);
        refreshAssumptions();
      };
      dec.onclick = () => set(q.value[r.key] - 1);
      inc.onclick = () => set(q.value[r.key] + 1);
      const step = el("div", "stepper");
      step.append(dec, n, inc);
      row.append(el("span", "nm", r.label), step);
      grid.append(row);
    });
    return grid;
  }

  if (q.type === "plot") {
    const wrap = el("div", "pair");
    const w = el("input"), d = el("input");
    Object.assign(w, { type: "number", id: `f-${q.id}`, value: q.def[0], min: 5, max: 100 });
    Object.assign(d, { type: "number", value: q.def[1], min: 5, max: 100 });
    q.value = [...q.def];
    const upd = () => { q.value = [Number(w.value) || q.def[0], Number(d.value) || q.def[1]]; };
    w.oninput = upd; d.oninput = upd;
    wrap.append(w, el("span", null, "×"), d, el("span", null, "m"));
    return wrap;
  }

  const i = el("input");
  Object.assign(i, { type: "text", id: `f-${q.id}`, placeholder: q.placeholder || "" });
  i.oninput = () => { q.value = i.value; };
  q.value = "";
  return i;
}

/* Every value we infer is shown, with the reason. The silent default is the
   failure mode this whole product is designed against. */
function refreshAssumptions() {
  const dwellings = QUESTIONS.find((q) => q.id === "dwelling_count").value || 1;
  const chips = [
    ["ceiling height", "2.50 m", "BayBO Art. 45 (1) minimum 2.40 m + 100 mm build-up"],
    ["storeys", "1", "v1 designs a single storey"],
    ["glazing", "1/8 of floor area", "BayBO Art. 45 (2)"],
  ];
  if (dwellings > 2) {
    chips.push(["barrier-free", "DIN 18040-2", "BayBO Art. 48 (1): more than 2 homes"]);
  }
  const box = $("assumed-chips");
  box.innerHTML = "";
  chips.forEach(([k, v, basis]) => {
    const c = el("span", "chip");
    c.append(el("span", null, k + " "), el("b", null, v), el("span", "basis", "· " + basis));
    box.append(c);
  });
}

function briefFromInterview() {
  const get = (id) => QUESTIONS.find((q) => q.id === id).value;
  const rooms = Object.entries(get("rooms"))
    .filter(([, n]) => n > 0)
    .map(([category, count]) => ({ category, count }));
  const [w, d] = get("plot");
  return {
    project: "Neubau",
    building_class: get("building_class"),
    dwelling_count: get("dwelling_count"),
    plot_width_m: w, plot_depth_m: d,
    rooms, notes: get("notes"),
    storey_count: 1, storey_height_m: 2.5, bundesland: "BY",
  };
}

/* ══════════════════════════════════════════════════════════════════════
   2 · The 3D viewer
   ══════════════════════════════════════════════════════════════════════ */

const COLOR = {
  bg: 0xffffff, wall: 0x9aa5ae, space: 0xdfe6ec,
  door: 0xd07a2a, window: 0x2a62d8, edge: 0x15191d,
  sky: 0xffffff, ground: 0xc7ced5,
};
const kindOf = (cls) =>
  cls === "IfcSpace" ? "space" : cls === "IfcDoor" ? "door" : cls === "IfcWindow" ? "window" : "wall";

let V = null;

function viewer() {
  if (V) return V;
  const host = $("v3-host");
  const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.domElement.className = "v3-canvas";
  host.append(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(COLOR.bg);
  const camera = new THREE.PerspectiveCamera(38, 1, 0.05, 2000);
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.09;

  scene.add(
    new THREE.HemisphereLight(COLOR.sky, COLOR.ground, 1.7),
    new THREE.AmbientLight(0xffffff, 0.35),
  );
  const sun = new THREE.DirectionalLight(0xffffff, 1.5);
  sun.position.set(1, 2, 1.4);
  scene.add(sun);

  V = { renderer, scene, camera, controls, host, root: null,
        raycaster: new THREE.Raycaster(), pointer: new THREE.Vector2(), spaces: [] };

  const resize = () => {
    const w = host.clientWidth || 1, h = host.clientHeight || 1;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  };
  new ResizeObserver(resize).observe(host);
  resize();

  host.addEventListener("pointermove", onHover);
  host.addEventListener("pointerleave", () => $("hoverchip").classList.add("hide"));

  (function loop() {
    requestAnimationFrame(loop);
    controls.update();
    renderer.render(scene, camera);
  })();
  return V;
}

function loadMesh(json) {
  const v = viewer();
  if (v.root) { v.scene.remove(v.root); disposeTree(v.root); }
  const root = new THREE.Group();
  v.spaces = [];

  const [x0, y0, z0, x1, y1, z1] = json.bounds;
  const mid = new THREE.Vector3((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2);

  for (const e of json.elements || []) {
    const kind = kindOf(e.cls);
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(e.verts, 3));
    g.setIndex(e.faces);
    const flat = g.toNonIndexed();     // flat shading keeps corners crisp
    flat.computeVertexNormals();
    g.dispose();
    flat.translate(-mid.x, -mid.y, -mid.z);

    const mat = new THREE.MeshLambertMaterial({
      color: COLOR[kind],
      transparent: kind === "space",
      opacity: kind === "space" ? 0.32 : 1,
      depthWrite: kind !== "space",
      side: kind === "space" ? THREE.DoubleSide : THREE.FrontSide,
    });
    const mesh = new THREE.Mesh(flat, mat);
    mesh.userData = { tag: e.tag, name: e.name, kind, area: e.area };
    if (kind === "space") v.spaces.push(mesh);
    root.add(mesh);
  }

  // IFC is Z-up; three.js is Y-up.
  root.rotation.x = -Math.PI / 2;
  v.scene.add(root);
  v.root = root;

  const span = Math.max(x1 - x0, y1 - y0, z1 - z0) || 10;
  v.camera.position.set(span * 0.95, span * 0.78, span * 1.05);
  v.controls.target.set(0, 0, 0);
  v.controls.update();
  applySpaceVisibility();
  $("v3-wait").classList.add("hide");
}

function disposeTree(obj) {
  obj.traverse((o) => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) o.material.dispose();
  });
}

function applySpaceVisibility() {
  if (!V) return;
  const on = $("show-spaces").checked;
  V.spaces.forEach((m) => { m.visible = on; });
}

function onHover(ev) {
  const v = viewer();
  if (!v.root) return;
  const r = v.host.getBoundingClientRect();
  v.pointer.set(((ev.clientX - r.left) / r.width) * 2 - 1, -((ev.clientY - r.top) / r.height) * 2 + 1);
  v.raycaster.setFromCamera(v.pointer, v.camera);
  const hit = v.raycaster.intersectObjects(v.root.children, false)
    .find((h) => h.object.visible && h.object.userData.kind === "space");
  const chip = $("hoverchip");
  if (!hit) { chip.classList.add("hide"); return; }
  const d = hit.object.userData;
  chip.textContent = `${d.tag ? d.tag + "  " : ""}${d.name}${d.area ? "  ·  " + d.area + " m²" : ""}`;
  chip.style.left = `${ev.clientX - r.left}px`;
  chip.style.top = `${ev.clientY - r.top}px`;
  chip.classList.remove("hide");
}

/* ══════════════════════════════════════════════════════════════════════
   3 · Results
   ══════════════════════════════════════════════════════════════════════ */

const base = (p, c) => `data/${p}/${c}`;

async function openProject(key, candidate) {
  const run = await fetch(`data/${key}/run.json`).then((r) => r.json());
  State.run = run; State.project = key;
  State.candidate = candidate || run.winner || (run.candidates[0] || {}).name;
  show("result");
  $("doc-title").textContent = run.project;
  $("restart").classList.remove("hide");
  await showCandidate(State.candidate);
}

async function showCandidate(name) {
  State.candidate = name;
  const p = State.project, dir = base(p, name);

  const verdict = await fetch(`${dir}/verdict.json`).then((r) => r.json()).catch(() => null);
  renderStamp(verdict);
  renderFindings(verdict);
  renderRooms(verdict);
  renderOptions();

  // Two very different failures used to report the same thing. "No model" when
  // the truth was "this browser has no WebGL" sends you looking in the wrong
  // place, so the fetch and the render are caught separately.
  const wait = $("v3-wait");
  wait.textContent = "loading model…";
  wait.classList.remove("hide");
  fetch(`${dir}/mesh.json`)
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`mesh.json ${r.status}`))))
    .then((json) => {
      try {
        loadMesh(json);
      } catch (e) {
        wait.textContent = "3D needs WebGL, which this browser did not provide";
        wait.classList.remove("hide");
        console.error("3D render failed:", e);
      }
    })
    .catch(() => { wait.textContent = "no 3D model was published for this candidate"; });

  fetch(`${dir}/sheet.svg`).then((r) => (r.ok ? r.text() : Promise.reject()))
    .then((svg) => { $("sheet-host").innerHTML = svg; })
    .catch(() => { $("sheet-host").innerHTML = '<p class="hint">no sheet for this candidate</p>'; });
  $("pdf-link").href = `${dir}/sheet.pdf`;

  fetch(`${dir}/design.py`).then((r) => r.text())
    .then((src) => { $("tab-code").innerHTML = ""; $("tab-code").append(el("pre", "code", src)); })
    .catch(() => {});
}

function renderStamp(v) {
  const host = $("top-stamp");
  host.classList.remove("hide");
  host.innerHTML = "";
  if (!v) return;
  const s = el("span", `stamp ${v.ok ? "pass" : "fail"}`);
  s.append(el("span", null, v.ok ? "PASS" : "FAIL"));
  // Never a bare PASS: what we could not check is part of the answer.
  s.append(el("span", "cov",
    `${v.checked} checked · ${v.not_evaluated} not evaluated · ${v.failed} failed`));
  host.append(s);
}

const TIERS = [
  ["law", "Statute", "may block"],
  ["standard", "Standard", "blocks once triggered"],
  ["guidance", "Guidance", "advisory only"],
  ["house", "Practice", "advisory only"],
];

function renderFindings(v) {
  const box = $("tab-findings");
  box.innerHTML = "";
  if (!v) { box.append(el("p", "hint", "No compliance result.")); return; }

  const notable = (v.findings || []).filter((f) => f.status !== "passed");
  if (!notable.length) {
    box.append(el("p", "hint", "Every rule that could be evaluated passed."));
  }
  for (const [tier, label, note] of TIERS) {
    const items = notable.filter((f) => f.tier === tier);
    if (!items.length) continue;
    const g = el("div", "tier-group");
    const h = el("div", "tier-h");
    h.append(el("span", `tl ${tier}`, label), el("span", "tn", note));
    g.append(h);
    items.forEach((f) => {
      const d = el("div", `finding ${f.status}`);
      const r = el("div", "fr");
      r.append(el("span", "rid", f.rule_id));
      if (f.status === "not_evaluated") r.append(el("span", "hint", "not evaluated"));
      else if (f.blocking) r.append(el("span", "hint", "blocking"));
      d.append(r, el("div", "fm", f.message));
      const cite = el("div", "cite");
      if (f.url) {
        const a = el("a", null, f.citation);
        a.href = f.url; a.target = "_blank"; a.rel = "noopener";
        cite.append(a);
      } else cite.append(el("span", null, f.citation));
      d.append(cite);
      g.append(d);
    });
    box.append(g);
  }
}

function renderRooms(v) {
  const box = $("tab-rooms");
  box.innerHTML = "";
  const m = (v && v.metrics) || {};
  const t = el("table", "rooms");
  t.innerHTML = "<thead><tr><th>Metric</th><th>Value</th></tr></thead>";
  const body = el("tbody");
  const rows = [
    ["Rooms", m.rooms], ["Envelope", m.envelope_m2 && m.envelope_m2 + " m²"],
    ["Room area", m.room_area_m2 && m.room_area_m2 + " m²"],
    ["Circulation", m.circulation_m2 && m.circulation_m2 + " m²"],
    ["Usable ratio", m.usable_ratio && (m.usable_ratio * 100).toFixed(1) + " %"],
    ["Doors + windows", m.openings],
  ];
  rows.forEach(([k, val]) => {
    if (val == null) return;
    const tr = el("tr");
    tr.append(el("td", null, k), el("td", "n", String(val)));
    body.append(tr);
  });
  t.append(body);
  box.append(t);
}

function renderOptions() {
  const box = $("tab-options");
  box.innerHTML = "";
  const run = State.run;
  (run.candidates || []).forEach((c) => {
    const card = el("div", "opt-card" + (c.name === State.candidate ? " on" : ""));
    const h = el("div", "oh");
    h.append(el("span", "on-name", c.label || c.name));
    if (c.name === run.winner) h.append(el("span", "badge", "winner"));
    card.append(h);
    if (c.error) card.append(el("div", "od", c.error));
    const m = el("div", "om");
    m.append(el("span", null, `${c.checked} checked`),
             el("span", null, `${c.failed} failed`),
             el("span", null, `${c.not_evaluated} not evaluated`));
    card.append(m);
    card.onclick = () => showCandidate(c.name);
    box.append(card);
  });
  box.append(el("p", "chosen-note",
    "The winner was chosen by the scorer from the compliance result — not by a person and not by a model. Picking another here is a new view, not an approval."));
}

/* ══════════════════════════════════════════════════════════════════════
   Shell
   ══════════════════════════════════════════════════════════════════════ */

function show(which) {
  ["brief", "working", "result"].forEach((v) =>
    $(`view-${v}`).classList.toggle("hide", v !== which));
}

function toast(msg, ms = 4200) {
  const t = $("toast");
  t.textContent = msg;
  t.classList.remove("hide");
  clearTimeout(toast._t);
  toast._t = setTimeout(() => t.classList.add("hide"), ms);
}

const STEPS = [
  ["Brief sealed", "the last moment a person is involved"],
  ["Plan", "rooms, areas and adjacencies — no coordinates"],
  ["Translate", "plan → building code, zero model tokens"],
  ["Build", "IFC4, sheets, 3D mesh"],
  ["Verify", "every rule, with its citation"],
  ["Rank", "the scorer picks a winner"],
];

function renderSteps(activeIdx) {
  const list = $("steps");
  list.innerHTML = "";
  STEPS.forEach(([lb, rt], i) => {
    const li = el("li", "step " + (i < activeIdx ? "done" : i === activeIdx ? "run" : "pend"));
    li.append(el("span", "dot"), el("span", "lb", lb), el("span", "rt", rt));
    list.append(li);
  });
}

/* A static page cannot run the pipeline. Rather than fake it, the Studio says
   plainly what to run, hands over the brief, and shows what already exists. */
async function submitBrief(ev) {
  ev.preventDefault();
  State.brief = briefFromInterview();
  show("working");
  $("working-title").textContent = "Ready to run";
  let i = 0;
  renderSteps(0);
  const tick = setInterval(() => {
    i += 1;
    renderSteps(Math.min(i, 1));
    if (i >= 1) {
      clearInterval(tick);
      $("working-sub").textContent =
        "This page is static, so it cannot run the pipeline itself. Your brief is ready — run it, or open a design that already exists.";
      $("working-note").innerHTML =
        `uv run recognition autopilot &lt;your-brief.json&gt;`;
      const blob = new Blob([JSON.stringify(State.brief, null, 2)], { type: "application/json" });
      const a = el("a", "primary", "Download the brief");
      a.href = URL.createObjectURL(blob);
      a.download = "brief.json";
      a.style.display = "inline-block";
      a.style.textDecoration = "none";
      const back = el("button", "ghost", "Look at a finished design");
      back.type = "button";
      back.onclick = () => { show("brief"); document.getElementById("existing").scrollIntoView({ behavior: "smooth" }); };
      const row = el("div", "brief-actions");
      row.append(a, back);
      $("steps").after(row);
    }
  }, 420);
}

async function boot() {
  renderInterview();
  $("interview").addEventListener("submit", submitBrief);
  $("show-spaces").addEventListener("change", applySpaceVisibility);
  $("restart").addEventListener("click", () => {
    show("brief");
    $("top-stamp").classList.add("hide");
    $("restart").classList.add("hide");
    $("doc-title").textContent = "A house, described";
  });
  document.querySelectorAll(".tabs button").forEach((b) => {
    b.onclick = () => {
      document.querySelectorAll(".tabs button").forEach((x) => x.classList.toggle("on", x === b));
      ["findings", "rooms", "options", "code"].forEach((t) =>
        $(`tab-${t}`).classList.toggle("hide", t !== b.dataset.tab));
    };
  });

  let index = { projects: [] };
  try {
    index = await fetch("data/index.json").then((r) => r.json());
  } catch {
    $("existing").classList.add("hide");
  }

  const grid = $("proj-grid");
  grid.innerHTML = "";
  if (!index.projects.length) $("existing").classList.add("hide");
  index.projects.forEach((p) => {
    const b = el("button", "proj");
    b.type = "button";
    b.append(el("div", "pn", p.project));
    b.append(el("div", "pm",
      `${p.candidates} layouts · ${p.checked} checked · ${p.not_evaluated} not evaluated · ${p.failed} failed`));
    b.onclick = () => openProject(p.key);
    grid.append(b);
  });

  // Deep link: ?p=familienhaus&c=open
  const q = new URLSearchParams(location.search);
  if (q.get("p")) openProject(q.get("p"), q.get("c"));
}

boot().catch((e) => toast("Could not start the Studio: " + e.message));

"""Engines: who produces the package for a job.

* ``LocalEngine`` runs ``recognition run`` in a subprocess on this machine and
  ticks the step list by watching the output directory fill up (the CLI only
  prints when it is finished, so the files *are* the progress signal).
* ``DevinEngine`` uploads the model, opens a Devin session (API v1 — the key
  format this org has) that works in the GitHub repo, and pulls the package
  Devin committed on its branch back into the job directory.

Both expose the same four calls so the web layer does not care which one it
is talking to.
"""
from __future__ import annotations

import json
import os
import re
import subprocess
import sys
import threading
import time
from pathlib import Path
from typing import Protocol

import httpx
import yaml

from .jobs import DEVIN_STEPS, LOCAL_STEPS, REPO_ROOT, Job, Run, slug

DEFAULT_RULES = REPO_ROOT / "rules" / "residential.yaml"
DEVIN_API = "https://api.devin.ai/v1"
PACKAGE_DIR = "deliveries"  # tracked folder where a Devin session commits the package
UI_PLAYBOOK = REPO_ROOT / "playbooks" / "detailing-ui.devin.md"


class EngineError(Exception):
    """A request the engine cannot honour; the message is shown to the architect."""


class Engine(Protocol):
    name: str

    def start(self, job: Job, ifc_path: Path, instruction: str | None, rules_yaml: str | None) -> None: ...
    def poll(self, job: Job) -> None: ...
    def message(self, job: Job, text: str, rules_yaml: str | None = None) -> None: ...
    def approve(self, job: Job) -> None: ...


def load_dotenv(path: Path = REPO_ROOT / ".env") -> None:
    """Tiny .env reader so ``uv run recognition-ui`` picks up credentials without another dependency."""
    if not path.exists():
        return
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        os.environ.setdefault(k.strip(), v.strip().strip("'\""))


def default_rules_yaml() -> str:
    return DEFAULT_RULES.read_text(encoding="utf-8")


def validate_rules(text: str) -> dict:
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as e:
        raise EngineError(f"Rules YAML does not parse: {e}") from e
    if not isinstance(data, dict) or not isinstance(data.get("rules"), list):
        raise EngineError("Rules YAML needs a top-level `rules:` list.")
    return data


def rules_changed(job: Job, rules_yaml: str | None) -> bool:
    if rules_yaml is None:
        return False
    current = job.rules_yaml if job.rules_yaml is not None else default_rules_yaml()
    return rules_yaml.strip() != current.strip()


# --- local ------------------------------------------------------------------

class LocalEngine:
    name = "local"

    def __init__(self, python: str = sys.executable, poll_interval: float = 0.2):
        self.python = python
        self.poll_interval = poll_interval

    def start(self, job: Job, ifc_path: Path, instruction: str | None, rules_yaml: str | None) -> None:
        job.instruction = instruction or None
        if rules_yaml is not None and rules_changed(job, rules_yaml):
            validate_rules(rules_yaml)
            job.rules_yaml = rules_yaml
        if job.instruction and job.rules_yaml is None:
            job.note = ("Free-text requests need Devin mode. The baseline package was generated with the "
                        "default rules; edit the rules below to re-run locally.")
        self._launch(job, "initial", job.instruction, job.rules_yaml)

    def poll(self, job: Job) -> None:  # the worker thread keeps the job current
        return

    def message(self, job: Job, text: str, rules_yaml: str | None = None) -> None:
        if rules_yaml is not None and rules_changed(job, rules_yaml):
            validate_rules(rules_yaml)
            job.rules_yaml = rules_yaml
            job.note = None
            self._launch(job, "rules", text or None, rules_yaml)
            return
        if text and text.strip():
            raise EngineError("Free-text requests need Devin mode; this server runs locally. "
                              "Edit the rules YAML and apply it to re-run here.")
        raise EngineError("Nothing changed — edit the rules or describe a change.")

    def approve(self, job: Job) -> None:
        if job.status != "done":
            raise EngineError("Nothing to approve yet.")
        job.approved = True
        job.approved_at = time.time()

    # --- internals -------------------------------------------------------

    def _launch(self, job: Job, trigger: str, instruction: str | None, rules_yaml: str | None) -> None:
        if job.status == "running":
            raise EngineError("A run is already in progress.")
        run = job.new_run(trigger, instruction, rules_yaml)
        job.reset_steps(LOCAL_STEPS)
        t = threading.Thread(target=self._worker, args=(job, run), daemon=True, name=f"run-{job.id}-{run.index}")
        t.start()

    def _command(self, job: Job, run: Run) -> list[str]:
        cmd = [self.python, "-m", "recognition.cli", "run", job.model_path, run.out_dir, "--project", job.project]
        if run.rules_yaml is not None:
            rules_path = Path(run.out_dir) / "rules.yaml"
            rules_path.write_text(run.rules_yaml, encoding="utf-8")
            cmd += ["--rules", str(rules_path)]
        return cmd

    def _worker(self, job: Job, run: Run) -> None:
        out = Path(run.out_dir)
        job.set_step("Load model", "running", Path(job.model_path).name)
        try:
            proc = subprocess.Popen(self._command(job, run), cwd=REPO_ROOT, stdout=subprocess.PIPE,
                                    stderr=subprocess.PIPE, text=True)
        except OSError as e:
            job.fail_run(run, f"could not start pipeline: {e}")
            return
        while proc.poll() is None:
            self._tick(job, out)
            time.sleep(self.poll_interval)
        self._tick(job, out)
        _, err = proc.communicate()
        summary_p = out / "summary.json"
        if proc.returncode == 0 and summary_p.exists():
            summary = json.loads(summary_p.read_text(encoding="utf-8"))
            self._final_details(job, summary)
            job.finish_run(run, summary)
        else:
            tail = "\n".join((err or "").strip().splitlines()[-8:]) or f"pipeline exited with {proc.returncode}"
            job.fail_run(run, tail)

    @staticmethod
    def _tick(job: Job, out: Path) -> None:
        """Advance steps from what the pipeline has written so far (it writes in this order)."""
        if (out / "schedules").exists():
            job.set_step("Load model", "done")
            job.set_step("Schedules", "running" if not (out / "report.json").exists() else "done")
        if (out / "report.json").exists():
            job.set_step("Schedules", "done")
            if job.step("Compliance").status != "done":
                try:
                    s = json.loads((out / "report.json").read_text(encoding="utf-8"))["summary"]
                    job.set_step("Compliance", "done", f"{s['checks']} checks · {s['errors']} errors · {s['warnings']} warnings")
                except (OSError, ValueError, KeyError):
                    job.set_step("Compliance", "running")
            job.set_step("Sheets", "running" if job.step("Sheets").status == "pending" else job.step("Sheets").status)
        sheets = out / "sheets"
        if sheets.exists():
            pngs = sorted(p.stem for p in sheets.glob("*.png"))
            if pngs and job.step("Sheets").status != "done":
                job.set_step("Sheets", "running", " · ".join(p.split("_", 1)[0] for p in pngs))
        if (out / "model.detailed.ifc").exists():
            job.set_step("Sheets", "done")
            job.set_step("Enriched IFC", "running")
        if (out / "summary.json").exists():
            job.set_step("Enriched IFC", "done")

    @staticmethod
    def _final_details(job: Job, summary: dict) -> None:
        c = summary["counts"]
        job.set_step("Load model", "done", f"{c['storeys']} storeys · {c['walls']} walls · {c['spaces']} rooms · "
                                           f"{c['doors']} doors · {c['windows']} windows")
        s = summary["schedules"]
        job.set_step("Schedules", "done", f"{s['rooms']} rooms · {s['doors']} doors · {s['windows']} windows")
        job.set_step("Sheets", "done", " · ".join(f"{sh['sheet']} {sh['storey']}" for sh in summary["sheets"]))
        job.set_step("Enriched IFC", "done", summary["files"]["enriched_ifc"])


# --- devin ------------------------------------------------------------------

class DevinClient:
    """Thin wrapper over the Devin v1 REST API; swapped for a fake in tests."""

    def __init__(self, api_key: str, base_url: str = DEVIN_API, timeout: float = 120.0):
        self.http = httpx.Client(base_url=base_url, headers={"Authorization": f"Bearer {api_key}"}, timeout=timeout)

    def upload(self, path: Path) -> str:
        with path.open("rb") as fh:
            r = self.http.post("/attachments", files={"file": (path.name, fh, "application/octet-stream")})
        r.raise_for_status()
        return r.text.strip().strip('"')

    def create_session(self, body: dict) -> dict:
        r = self.http.post("/sessions", json=body)
        r.raise_for_status()
        return r.json()

    def get_session(self, session_id: str) -> dict:
        r = self.http.get(f"/sessions/{session_id}")
        r.raise_for_status()
        return r.json()

    def send_message(self, session_id: str, text: str) -> None:
        r = self.http.post(f"/sessions/{session_id}/message", json={"message": text})
        r.raise_for_status()

    def create_playbook(self, title: str, body: str, macro: str | None = None) -> dict:
        r = self.http.post("/playbooks", json={"title": title, "body": body, "macro": macro})
        r.raise_for_status()
        return r.json()


STRUCTURED_OUTPUT_SCHEMA = {
    "type": "object",
    "properties": {
        "branch": {"type": "string", "description": "git branch the package was committed to"},
        "pr_url": {"type": "string", "description": "URL of the pull request"},
        "package_dir": {"type": "string", "description": "repo-relative directory holding summary.json"},
        "status": {"type": "string", "enum": ["PASS", "WARN", "FAIL"]},
        "checks": {"type": "integer"}, "errors": {"type": "integer"}, "warnings": {"type": "integer"},
        "sheets": {"type": "integer"},
        "changed": {"type": "string", "description": "one paragraph: what you changed in the repo and why"},
        "assumptions": {"type": "string"},
    },
    "required": ["branch", "package_dir", "status"],
}


def devin_configured() -> bool:
    return bool(os.environ.get("DEVIN_API_KEY"))


def github_repo() -> str:
    """owner/name of the origin remote, unless GITHUB_REPO overrides it."""
    if os.environ.get("GITHUB_REPO"):
        return os.environ["GITHUB_REPO"]
    try:
        url = subprocess.check_output(["git", "remote", "get-url", "origin"], cwd=REPO_ROOT, text=True).strip()
    except (OSError, subprocess.CalledProcessError):
        return ""
    m = re.search(r"github\.com[:/]([^/]+/[^/.]+)", url)
    return m.group(1) if m else ""


class DevinEngine:
    name = "devin"

    def __init__(self, client: DevinClient | None = None, repo: str | None = None, git_dir: Path = REPO_ROOT,
                 poll_interval: float = 2.0, max_acu: int | None = None):
        self.client = client or DevinClient(os.environ["DEVIN_API_KEY"])
        self.repo = repo if repo is not None else github_repo()
        self.git_dir = git_dir
        self.poll_interval = poll_interval
        self.max_acu = max_acu or int(os.environ.get("DEVIN_MAX_ACU", "5"))
        self.playbook_id = os.environ.get("DEVIN_PLAYBOOK_ID") or None
        self._last_poll: dict[str, float] = {}
        self._last_commit: dict[str, str] = {}

    # --- protocol --------------------------------------------------------

    def start(self, job: Job, ifc_path: Path, instruction: str | None, rules_yaml: str | None) -> None:
        if job.status == "running":
            raise EngineError("A run is already in progress.")
        job.engine = "devin"
        job.instruction = instruction or None
        if rules_yaml is not None and rules_changed(job, rules_yaml):
            validate_rules(rules_yaml)
            job.rules_yaml = rules_yaml
        job.note = None
        job.branch = job.branch or f"detail/{slug(job.project).lower()}-{job.id[:6]}"
        run = job.new_run("devin", job.instruction, job.rules_yaml)
        job.reset_steps(DEVIN_STEPS)
        threading.Thread(target=self._open_session, args=(job, run, ifc_path), daemon=True).start()

    def poll(self, job: Job) -> None:
        if not job.devin_session_id or job.status != "running":
            return
        now = time.time()
        if now - self._last_poll.get(job.id, 0) < self.poll_interval:
            return
        self._last_poll[job.id] = now
        try:
            s = self.client.get_session(job.devin_session_id)
        except httpx.HTTPError as e:
            job.set_step("Working", "running", f"polling failed: {e}")
            return
        self._apply_session(job, s)

    def message(self, job: Job, text: str, rules_yaml: str | None = None) -> None:
        if not job.devin_session_id:
            raise EngineError("No Devin session for this job.")
        if job.status == "running" and not job.devin_waiting:
            raise EngineError("Devin is still working on the previous request.")
        parts = [text.strip()] if text and text.strip() else []
        if rules_yaml is not None and rules_changed(job, rules_yaml):
            validate_rules(rules_yaml)
            job.rules_yaml = rules_yaml
            parts.append("Apply this ruleset (write it to the package directory as rules.yaml and pass it with --rules):\n"
                         f"```yaml\n{rules_yaml.strip()}\n```")
        if not parts:
            raise EngineError("Nothing changed — describe a change or edit the rules.")
        parts.append(f"Regenerate the package under {PACKAGE_DIR}/{slug(job.project)}/ on branch {job.branch}, "
                     "commit, push, update the pull request, and call the structured output tool again.")
        self.client.send_message(job.devin_session_id, "\n\n".join(parts))
        job.devin_waiting = False
        if job.status == "running":  # a reply to a blocked session continues the current run
            job.set_step("Working", "running", "reply sent")
            job.devin_message = None
            return
        run = job.new_run("devin", text or None, job.rules_yaml)
        job.reset_steps(DEVIN_STEPS)
        job.set_step("Upload model", "done", "attached to session")
        job.set_step("Devin session", "done", job.devin_session_id)
        job.set_step("Working", "running", "request sent")
        job.devin_message = None
        run.commit = None

    def approve(self, job: Job) -> None:
        if not job.pr_url:
            raise EngineError("No pull request to merge yet.")
        if job.approved:
            return
        self._merge(job.pr_url)
        job.approved = True
        job.approved_at = time.time()

    # --- internals -------------------------------------------------------

    def prompt(self, job: Job, attachment_url: str | None) -> str:
        pkg = f"{PACKAGE_DIR}/{slug(job.project)}"
        lines = [
            job.instruction or "Produce the detailing package for the attached model.",
            "",
            f"Repository: https://github.com/{self.repo} — base branch `poc/ifc-detailing`. Work on branch `{job.branch}`.",
            f"Model: {job.model_name} (attached). Project name: \"{job.project}\".",
            f"Commit the generated package to `{pkg}/` (summary.json, report.json, report.md, schedules/, sheets/, "
            "model.detailed.ifc) and open a pull request against `poc/ifc-detailing`.",
            "When done, call the structured output tool with branch, pr_url, package_dir and the compliance counts.",
        ]
        if not self.playbook_id and UI_PLAYBOOK.exists():
            lines += ["", "Follow this playbook:", "", UI_PLAYBOOK.read_text(encoding="utf-8")]
        if job.rules_yaml:
            lines += ["", f"Use this ruleset instead of rules/residential.yaml (save it as `{pkg}/rules.yaml` and pass "
                          "`--rules`):", "```yaml", job.rules_yaml.strip(), "```"]
        if attachment_url:
            lines += ["", f'ATTACHMENT:"{attachment_url}"']
        return "\n".join(lines)

    def _open_session(self, job: Job, run: Run, ifc_path: Path) -> None:
        try:
            job.set_step("Upload model", "running", f"{ifc_path.name} ({ifc_path.stat().st_size / 1e6:.1f} MB)")
            url = self.client.upload(ifc_path)
            job.set_step("Upload model", "done", ifc_path.name)
            job.set_step("Devin session", "running", "creating")
            body = {
                "prompt": self.prompt(job, url),
                "title": f"{job.project} — {job.instruction or 'detailing package'}"[:120],
                "tags": ["recognition", "ui"],
                "max_acu_limit": self.max_acu,
                "structured_output_schema": STRUCTURED_OUTPUT_SCHEMA,
            }
            if self.playbook_id:
                body["playbook_id"] = self.playbook_id
            s = self.client.create_session(body)
            job.devin_session_id = s["session_id"]
            job.devin_session_url = s.get("url")
            job.set_step("Devin session", "done", s["session_id"])
            job.set_step("Working", "running", "session started")
        except (httpx.HTTPError, OSError, KeyError) as e:
            job.fail_run(run, f"Devin API: {e}")

    def _apply_session(self, job: Job, s: dict) -> None:
        run = job.current_run()
        msgs = [m for m in s.get("messages", []) if m.get("type") == "devin_message"]
        if msgs:
            job.devin_message = msgs[-1].get("message")
        if s.get("acus_consumed") is not None:
            job.devin_acus = s["acus_consumed"]
        pr = s.get("pull_request") or {}
        if pr.get("url"):
            job.pr_url = pr["url"]
            job.set_step("Pull request", "done", pr["url"])
        enum = s.get("status_enum") or s.get("status")
        so = s.get("structured_output") or {}
        branch = so.get("branch") or job.branch
        if so.get("pr_url") and not job.pr_url:
            job.pr_url = so["pr_url"]
            job.set_step("Pull request", "done", so["pr_url"])
        if enum in ("expired", "error") and not so:
            job.fail_run(run, f"Devin session {enum}")
            return
        if so:
            commit = self._remote_head(branch)
            if commit and commit != self._last_commit.get(job.id):
                job.set_step("Working", "done", so.get("changed") or "done")
                job.set_step("Fetch package", "running", f"{branch} @ {commit[:7]}")
                try:
                    self._fetch_package(branch, so.get("package_dir") or f"{PACKAGE_DIR}/{slug(job.project)}", Path(run.out_dir))
                except (OSError, subprocess.CalledProcessError, ValueError) as e:
                    job.fail_run(run, f"could not fetch package from {branch}: {e}")
                    return
                self._last_commit[job.id] = commit
                run.commit = commit
                job.branch = branch
                summary = json.loads((Path(run.out_dir) / "summary.json").read_text(encoding="utf-8"))
                job.set_step("Fetch package", "done", f"{commit[:7]} · {summary['compliance']['status']}")
                if not job.pr_url:
                    job.set_step("Pull request", "done", "not opened")
                job.finish_run(run, summary)
                return
        job.devin_waiting = enum == "blocked"
        if job.devin_waiting:
            job.set_step("Working", "running", "Devin is waiting for your answer — reply below")
        elif enum == "working":
            job.set_step("Working", "running", (job.devin_message or "working")[:160])

    def _remote_head(self, branch: str) -> str | None:
        try:
            out = subprocess.check_output(["git", "ls-remote", "origin", f"refs/heads/{branch}"], cwd=self.git_dir,
                                          text=True, stderr=subprocess.DEVNULL, timeout=30)
        except (OSError, subprocess.CalledProcessError, subprocess.TimeoutExpired):
            return None
        return out.split()[0] if out.strip() else None

    def _fetch_package(self, branch: str, package_dir: str, dest: Path) -> None:
        subprocess.run(["git", "fetch", "--quiet", "origin", branch], cwd=self.git_dir, check=True, timeout=120)
        dest.mkdir(parents=True, exist_ok=True)
        depth = len(Path(package_dir).parts)
        archive = subprocess.run(["git", "archive", f"origin/{branch}", package_dir], cwd=self.git_dir,
                                 check=True, capture_output=True, timeout=120)
        subprocess.run(["tar", "-x", f"--strip-components={depth}", "-C", str(dest)], input=archive.stdout,
                       check=True, timeout=120)
        if not (dest / "summary.json").exists():
            raise ValueError(f"{package_dir} on {branch} has no summary.json")

    def _merge(self, pr_url: str) -> None:
        token = os.environ.get("GITHUB_TOKEN")
        if token:
            m = re.search(r"github\.com/([^/]+/[^/]+)/pull/(\d+)", pr_url)
            if not m:
                raise EngineError(f"unrecognised PR URL {pr_url}")
            r = httpx.put(f"https://api.github.com/repos/{m.group(1)}/pulls/{m.group(2)}/merge",
                          headers={"Authorization": f"Bearer {token}", "Accept": "application/vnd.github+json"},
                          json={"merge_method": "squash"}, timeout=60)
            if r.status_code >= 300:
                raise EngineError(f"GitHub merge failed: {r.status_code} {r.text[:200]}")
            return
        try:
            subprocess.run(["gh", "pr", "merge", pr_url, "--squash"], cwd=self.git_dir, check=True,
                           capture_output=True, text=True, timeout=120)
        except FileNotFoundError as e:
            raise EngineError("Set GITHUB_TOKEN or install gh to merge pull requests.") from e
        except subprocess.CalledProcessError as e:
            raise EngineError(f"gh pr merge failed: {(e.stderr or '').strip()[:300]}") from e


def make_engine(name: str) -> Engine:
    if name == "devin":
        if not devin_configured():
            raise EngineError("Devin mode is not configured on this server (DEVIN_API_KEY missing).")
        return DevinEngine()
    return LocalEngine()

