/* Recognition Studio — a drawing-office light table.
   The sheet is the hero; the rest is the instrument panel.

   Tokens carried forward from ui/static/style.css so the product and the
   internal tools look like one system. Three rules hold the whole thing
   together: the drawing gets the contrast, every number is monospace, and
   verdict colour is never decoration. */

:root {
  --board: #E4E8EC; --board-2: #D8DEE3; --paper: #FFFFFF; --paper-2: #F6F8F9;
  --ink: #15191D; --ink-2: #59646E; --ink-3: #8A949D;
  --line: #C7CED5; --line-2: #E1E6EA;
  --accent: #2A62D8; --accent-soft: #E3ECFB;
  --pass: #167A4C; --pass-soft: #DDF3E6;
  --warn: #B8740A; --warn-soft: #FBEFD6;
  --fail: #C8352A; --fail-soft: #FBE3E0;
  --font-ui: "Familjen Grotesk", "Helvetica Neue", Arial, system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, monospace;
  --radius: 4px;
  --shadow-sheet: 0 1px 2px rgba(20,25,29,.10), 0 18px 40px -14px rgba(20,25,29,.35);
  --shadow-card: 0 1px 2px rgba(20,25,29,.06), 0 6px 18px -10px rgba(20,25,29,.2);
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  background: var(--board); color: var(--ink);
  font-family: var(--font-ui); font-size: 14px; line-height: 1.45;
  -webkit-font-smoothing: antialiased;
  display: flex; flex-direction: column; overflow: hidden;
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font: inherit; color: inherit; }
code, .mono { font-family: var(--font-mono); font-size: 12.5px; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.hide { display: none !important; }
.spacer { flex: 1; }
.hint { color: var(--ink-3); font-size: 12.5px; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } }

/* --- header ------------------------------------------------------------- */
.top {
  display: flex; align-items: center; gap: 16px; padding: 0 22px; height: 56px;
  border-bottom: 1px solid var(--line); background: var(--paper); flex: none; z-index: 5;
}
.wordmark { display: flex; align-items: center; gap: 9px; font-weight: 700; letter-spacing: .02em; font-size: 15px; color: var(--ink); }
.wordmark:hover { text-decoration: none; }
.wordmark svg { width: 22px; height: 22px; }
