.room-row.on { background: var(--accent-soft); border-color: #BBD1F5; }

.q input[type=text], .q input[type=number] {
  font: inherit; padding: 8px 11px; border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--paper); width: 100%; max-width: 320px;
}
