.primary {
  background: var(--accent); color: #fff; border: 0; border-radius: var(--radius);
  padding: 11px 22px; font-size: 15px; font-weight: 600; cursor: pointer;
}
.primary:hover { background: #2455BC; }
.primary:disabled { background: var(--line); cursor: default; }

.existing { margin-top: 46px; border-top: 1px solid var(--line); padding-top: 22px; }
.existing h3 { font-size: 14px; font-weight: 600; margin: 0 0 12px; }
.proj-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 10px; }
.proj {
  text-align: left; background: var(--paper); border: 1px solid var(--line-2); border-radius: 6px;
  padding: 13px 15px; cursor: pointer; box-shadow: var(--shadow-card); display: block; width: 100%;
}
.proj:hover { border-color: var(--accent); }
.proj .pn { font-weight: 600; font-size: 14.5px; margin-bottom: 5px; }
.proj .pm { font-family: var(--font-mono); font-size: 11.5px; color: var(--ink-3); }

/* --- 2 · working -------------------------------------------------------- */
.working-wrap { max-width: 640px; margin: 0 auto; padding: 70px 24px; }
.working-wrap h2 { font-size: 24px; margin: 0 0 6px; font-weight: 600; letter-spacing: -.01em; }
.working-wrap .sub { color: var(--ink-2); margin: 0 0 30px; }
.steps { list-style: none; margin: 0 0 22px; padding: 0; display: flex; flex-direction: column; gap: 2px; }
.step { display: flex; align-items: center; gap: 12px; padding: 11px 14px; border-radius: var(--radius); background: var(--paper); border: 1px solid var(--line-2); }
.step .dot { width: 9px; height: 9px; border-radius: 50%; background: var(--line); flex: none; }
.step.run .dot { background: var(--accent); animation: pulse 1.1s ease-in-out infinite; }
.step.done .dot { background: var(--pass); }
.step.fail .dot { background: var(--fail); }
.step .lb { flex: 1; }
.step .rt { font-family: var(--font-mono); font-size: 12px; color: var(--ink-3); }
.step.pend { opacity: .5; }
@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: .35; } }

/* --- 3 · result --------------------------------------------------------- */
.studio {
  display: grid; gap: 14px; padding: 14px 18px 16px;
  grid-template-columns: minmax(0,1.35fr) minmax(320px, 0.85fr);
  grid-template-rows: minmax(0,1fr) minmax(0,1fr);
  overflow: hidden;
}
.pane { background: var(--paper); border: 1px solid var(--line-2); border-radius: 6px; box-shadow: var(--shadow-card); display: flex; flex-direction: column; min-height: 0; overflow: hidden; }
.pane-head { display: flex; align-items: center; gap: 10px; padding: 8px 13px; border-bottom: 1px solid var(--line-2); min-height: 40px; flex: none; }
.pane-head strong { font-size: 13px; letter-spacing: .04em; text-transform: uppercase; font-family: var(--font-mono); font-weight: 600; }
.pane-3d { grid-column: 1; grid-row: 1; }
.pane-2d { grid-column: 1; grid-row: 2; }
.pane-side { grid-column: 2; grid-row: 1 / span 2; }

.v3-host { position: relative; flex: 1; min-height: 0; overflow: hidden; background: var(--paper); cursor: grab; }
.v3-host:active { cursor: grabbing; }
.v3-canvas { display: block; width: 100% !important; height: 100% !important; }
.v3-wait { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; color: var(--ink-3); font-family: var(--font-mono); font-size: 12.5px; }
.v3-opts { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--ink-2); cursor: pointer; }
.v3-opts input { margin: 0; }
.hoverchip {
  position: absolute; pointer-events: none; z-index: 3; background: var(--ink); color: var(--paper);
  font-family: var(--font-mono); font-size: 11.5px; padding: 5px 9px; border-radius: 4px; white-space: nowrap;
  transform: translate(-50%, -140%);
}

.sheet-host { flex: 1; min-height: 0; display: flex; align-items: center; justify-content: center; background: var(--board-2); padding: 12px; overflow: auto; }
.sheet-host svg, .sheet-host img { max-width: 100%; max-height: 100%; background: var(--paper); box-shadow: var(--shadow-sheet); }

.tabs { display: flex; gap: 2px; padding: 7px 9px; border-bottom: 1px solid var(--line-2); flex: none; }
.tabs button { background: none; border: 1px solid transparent; border-radius: var(--radius); padding: 5px 11px; cursor: pointer; font-size: 13px; color: var(--ink-2); }
.tabs button:hover { background: var(--paper-2); }
.tabs button.on { background: var(--ink); color: var(--paper); }
.tabbody { flex: 1; min-height: 0; overflow: auto; padding: 12px 14px; }

.tier-group { margin-bottom: 18px; }
.tier-h { display: flex; align-items: baseline; gap: 9px; margin-bottom: 7px; }
.tier-h .tl { font-family: var(--font-mono); font-size: 10.5px; letter-spacing: .1em; text-transform: uppercase; font-weight: 600; padding: 2px 7px; border-radius: 3px; }
.tl.law { background: var(--fail-soft); color: var(--fail); }
.tl.standard { background: var(--warn-soft); color: var(--warn); }
.tl.guidance { background: var(--accent-soft); color: var(--accent); }
.tl.house { background: var(--paper-2); color: var(--ink-3); }
.tier-h .tn { font-size: 12px; color: var(--ink-3); }

.finding { border-left: 3px solid var(--line); padding: 7px 0 7px 11px; margin-bottom: 8px; }
.finding.failed { border-left-color: var(--fail); }
.finding.not_evaluated { border-left-color: var(--ink-3); border-left-style: dashed; }
.finding.passed { border-left-color: var(--pass); }
.finding .fr { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.finding .rid { font-family: var(--font-mono); font-size: 11.5px; font-weight: 600; }
.finding .fm { font-size: 13px; color: var(--ink-2); margin: 2px 0 3px; }
.finding .cite { font-family: var(--font-mono); font-size: 11px; color: var(--ink-3); }
.finding .cite a { color: var(--ink-3); text-decoration: underline; }
.finding .cite a:hover { color: var(--accent); }

table.rooms { width: 100%; border-collapse: collapse; font-family: var(--font-mono); font-size: 12px; }
table.rooms th { text-align: left; font-size: 10px; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-3); padding: 6px 8px; border-bottom: 1px solid var(--line-2); font-weight: 600; }
table.rooms td { padding: 6px 8px; border-bottom: 1px solid var(--line-2); color: var(--ink-2); }
table.rooms td.n { text-align: right; font-variant-numeric: tabular-nums; color: var(--ink); }
table.rooms tr:hover td { background: var(--paper-2); }

.opt-card { border: 1px solid var(--line-2); border-radius: 6px; padding: 12px 14px; margin-bottom: 10px; cursor: pointer; background: var(--paper); }
.opt-card:hover { border-color: var(--accent); }
.opt-card.on { border-color: var(--ink); box-shadow: inset 0 0 0 1px var(--ink); }
.opt-card .oh { display: flex; align-items: baseline; gap: 9px; margin-bottom: 4px; }
.opt-card .on-name { font-weight: 600; font-size: 14px; }
.opt-card .badge { font-family: var(--font-mono); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; background: var(--pass-soft); color: var(--pass); padding: 2px 6px; border-radius: 3px; }
.opt-card .od { font-size: 12.5px; color: var(--ink-3); margin-bottom: 7px; }
.opt-card .om { font-family: var(--font-mono); font-size: 11.5px; color: var(--ink-2); display: flex; gap: 14px; flex-wrap: wrap; }
.chosen-note { font-size: 12.5px; color: var(--ink-3); border-top: 1px solid var(--line-2); padding-top: 10px; margin-top: 4px; }

pre.code { margin: 0; font-family: var(--font-mono); font-size: 11.5px; line-height: 1.55; white-space: pre; overflow: auto; color: var(--ink-2); }

.toast { position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%); background: var(--ink); color: var(--paper); padding: 10px 16px; border-radius: var(--radius); font-size: 13px; z-index: 20; box-shadow: var(--shadow-card); }

@media (max-width: 1080px) {
  .studio { grid-template-columns: 1fr; grid-template-rows: 320px 320px auto; overflow: auto; }
  .pane-3d, .pane-2d, .pane-side { grid-column: 1; }
  .pane-side { grid-row: 3; min-height: 420px; }
  .brief-intro h2 { font-size: 25px; }
}

