/* --- the interview: chat + the brief sheet ------------------------------ */
.mode-row { display: flex; gap: 2px; margin: 0 0 14px; border-bottom: 1px solid var(--line); }
.mode {
  background: none; border: 0; border-bottom: 2px solid transparent; border-radius: 0;
  padding: 8px 14px 9px; cursor: pointer; font-size: 14px; color: var(--ink-2); font-weight: 500;
}
.mode:hover { color: var(--ink); }
.mode.on { color: var(--ink); border-bottom-color: var(--accent); font-weight: 600; }

.brief-grid { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(300px, .85fr); gap: 16px; align-items: start; }

.chat-pane {
  background: var(--paper); border: 1px solid var(--line-2); border-radius: 6px;
  box-shadow: var(--shadow-card); display: flex; flex-direction: column;
  min-height: 480px; max-height: calc(100dvh - 300px);
}
.chat-head { display: flex; align-items: center; gap: 9px; padding: 9px 14px; border-bottom: 1px solid var(--line-2); flex: none; }
.chat-head strong { font-size: 13px; letter-spacing: .04em; text-transform: uppercase; font-family: var(--font-mono); font-weight: 600; }
.agent-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--accent); flex: none; }
.engine-pick { margin-right: -4px; }
select {
  font: inherit; font-size: 12.5px; color: var(--ink); background: var(--paper);
  border: 1px solid var(--line); border-radius: var(--radius); padding: 4px 6px; cursor: pointer;
}
select:hover { border-color: var(--ink-3); }
select:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
select:disabled { opacity: .45; cursor: default; }

.chat-log { list-style: none; margin: 0; padding: 14px; flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 10px; }
.msg { max-width: 86%; display: flex; flex-direction: column; gap: 3px; }
.msg .bubble {
  padding: 9px 13px; border-radius: 10px; font-size: 14px; line-height: 1.5;
  border: 1px solid var(--line-2); background: var(--paper-2); color: var(--ink);
  white-space: pre-wrap; overflow-wrap: anywhere;
}
.msg.you { align-self: flex-end; align-items: flex-end; }
.msg.you .bubble { background: var(--ink); color: var(--paper); border-color: var(--ink); border-bottom-right-radius: 3px; }
.msg.agent .bubble { border-bottom-left-radius: 3px; }
.msg.devin .bubble { border-left: 3px solid var(--accent); }
.msg .meta { font-family: var(--font-mono); font-size: 10.5px; color: var(--ink-3); padding: 0 3px; }
.msg .meta a { color: var(--ink-3); text-decoration: underline; }
.msg .meta a:hover { color: var(--accent); }
.msg .got { display: flex; flex-wrap: wrap; gap: 5px; padding-top: 2px; }
.msg .got .chip { padding: 3px 9px; font-size: 10.5px; }
.msg.wait .bubble { color: var(--ink-2); display: flex; align-items: center; gap: 9px; }
.msg.wait .bubble::before {
  content: ""; width: 9px; height: 9px; border-radius: 50%; background: var(--accent);
  animation: pulse 1.1s ease-in-out infinite; flex: none;
}
@media (prefers-reduced-motion: reduce) { .msg.wait .bubble::before { animation: none; } }

.chat-chips { display: flex; flex-wrap: wrap; gap: 7px; padding: 0 14px 10px; flex: none; }
.chat-chips:empty { display: none; }
.qchip {
  border: 1px solid var(--line); background: var(--paper); border-radius: 16px;
  padding: 6px 13px; cursor: pointer; font-size: 13px; color: var(--ink);
  transition: background .12s, border-color .12s;
}
.qchip:hover { border-color: var(--accent); color: var(--accent); }
.qchip:active { background: var(--accent-soft); }
.qchip:disabled { opacity: .45; cursor: default; }
.qchip:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }

.composer { display: flex; gap: 9px; padding: 11px 14px; border-top: 1px solid var(--line-2); flex: none; align-items: flex-end; }
.composer textarea {
  flex: 1; font: inherit; font-size: 14px; line-height: 1.45; resize: none;
  padding: 9px 12px; border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--paper); color: var(--ink); min-height: 40px; max-height: 130px;
}
.composer textarea::placeholder { color: var(--ink-3); }
.composer textarea:hover { border-color: var(--ink-3); }
.composer textarea:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px var(--accent-soft); }
.composer textarea:disabled { background: var(--paper-2); color: var(--ink-3); cursor: default; }
.composer .primary { padding: 9px 18px; min-height: 40px; }
.primary.sm { padding: 6px 13px; font-size: 13px; }
.primary:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }
.primary:active:not(:disabled) { transform: translateY(1px); }
.primary[data-state="busy"] { background: var(--line); color: var(--ink-2); cursor: progress; }

.brief-sheet {
  background: var(--paper); border: 1px solid var(--line-2); border-radius: 6px;
  box-shadow: var(--shadow-card); padding: 14px 16px 16px; position: sticky; top: 14px;
}
.sheet-title { display: flex; align-items: baseline; gap: 9px; padding-bottom: 9px; border-bottom: 2px solid var(--ink); margin-bottom: 4px; }
.sheet-title strong { font-family: var(--font-mono); font-size: 13px; letter-spacing: .05em; }
.sheet-fields { margin: 0 0 14px; }
.sheet-fields > div { display: flex; align-items: baseline; gap: 10px; padding: 6px 1px; border-bottom: 1px solid var(--line-2); }
.sheet-fields dt { flex: none; width: 92px; font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: var(--ink-3); }
.sheet-fields dd { margin: 0; font-family: var(--font-mono); font-size: 12.5px; color: var(--ink); min-width: 0; overflow-wrap: anywhere; }
.sheet-fields dd.empty { color: var(--ink-3); }
.sheet-fields dd .src { font-size: 10px; color: var(--ink-3); margin-left: 6px; }
.sheet-fields dd .src.devin { color: var(--accent); }
.brief-sheet .assumed { margin: 0 0 14px; padding: 11px 13px; }
.brief-sheet .brief-actions { gap: 9px; }
.brief-sheet #run-engine { flex: 1; min-width: 0; }

/* --- connect popover ---------------------------------------------------- */
.connect-wrap { position: relative; }
#connect[data-on="1"] { border-color: var(--pass); color: var(--pass); }
.pop {
  position: absolute; right: 0; top: calc(100% + 8px); width: min(340px, calc(100vw - 32px));
  background: var(--paper); border: 1px solid var(--line); border-radius: 6px;
  box-shadow: var(--shadow-sheet); padding: 14px 16px; z-index: 30;
}
.pop h3 { margin: 0 0 5px; font-size: 14px; }
.pop .hint { margin: 0 0 10px; }
.pop code { font-size: 11px; }
.pop-label { display: block; font-size: 11px; letter-spacing: .04em; text-transform: uppercase; color: var(--ink-2); margin: 0 0 5px; }
.pop input {
  width: 100%; font-family: var(--font-mono); font-size: 12.5px; padding: 8px 10px;
  border: 1px solid var(--line); border-radius: var(--radius); background: var(--paper);
}
