1	/* Recognition Studio.
2	 *
3	 * A static page. It reads artifacts a run already committed under data/ and
4	 * renders them; it never runs the pipeline itself and it never holds a secret.
5	 *
6	 * Two things happen live, and both go through GitHub with the *viewer's own*
7	 * token, never a stored one:
8	 *   - the interview can escalate from the instant rules engine to a real
9	 *     Devin session, relayed through the `interview` workflow (the browser
10	 *     cannot call the Devin API: CORS, and the key must stay server-side);
11	 *   - "Design it" can dispatch a real autopilot run and watch it to the
12	 *     merged, published result.
13	 *
14	 * Honesty rules carried from the product: every agent reply is labelled with
15	 * the engine that produced it, every inferred value is a visible assumption,
16	 * and no step ever ticks without a real event behind it.
17	 */
18	import * as THREE from "three";
19	import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/controls/OrbitControls.js";
20	
21	const $ = (id) => document.getElementById(id);
22	const el = (tag, cls, text) => {
23	  const n = document.createElement(tag);
24	  if (cls) n.className = cls;
25	  if (text != null) n.textContent = text;
26	  return n;
27	};
28	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
29	const REDUCED = matchMedia("(prefers-reduced-motion: reduce)").matches;
30	
31	const State = { run: null, project: null, candidate: null };
32	
33	/* ══════════════════════════════════════════════════════════════════════
34	   GitHub — the viewer's own credentials, api.github.com only
35	   ══════════════════════════════════════════════════════════════════════ */
36	
37	function detectRepo() {
38	  // studio served at <owner>.github.io/<repo>/ — derive; fall back for localhost.
39	  const host = location.hostname;
40	  if (host.endsWith(".github.io")) {
41	    const owner = host.split(".")[0];
42	    const seg = location.pathname.split("/").filter(Boolean)[0];
43	    if (owner && seg) return `${owner}/${seg}`;
44	  }
45	  return "0-uddeshya-0/Recognition";
46	}
47	
48	const GH = {
49	  repo: detectRepo(),
50	  get token() { return localStorage.getItem("recognition.gh_token") || ""; },
51	  set token(v) { v ? localStorage.setItem("recognition.gh_token", v) : localStorage.removeItem("recognition.gh_token"); },
52	  get on() { return !!this.token; },
53	
54	  async api(path, opts = {}) {
55	    const r = await fetch(`https://api.github.com${path}`, {
56	      ...opts,
57	      headers: {
58	        Accept: "application/vnd.github+json",
59	        Authorization: `Bearer ${this.token}`,
60	        "X-GitHub-Api-Version": "2022-11-28",
61	        ...(opts.headers || {}),
62	      },
63	    });
64	    if (r.status === 404) return null;
65	    if (!r.ok) throw new Error(`GitHub ${r.status}: ${(await r.text()).slice(0, 140)}`);
66	    return r.status === 204 ? true : r.json();
67	  },
68	
69	  dispatch(event_type, client_payload) {
70	    return this.api(`/repos/${this.repo}/dispatches`, {
71	      method: "POST",
72	      body: JSON.stringify({ event_type, client_payload }),
73	    });
74	  },
75	
76	  async raw(path, ref) {
77	    const r = await fetch(
78	      `https://api.github.com/repos/${this.repo}/contents/${path}?ref=${ref}&t=${Date.now()}`,
79	      { headers: { Accept: "application/vnd.github.raw+json", Authorization: `Bearer ${this.token}` } },
80	    );
81	    return r.ok ? r.json() : null;
82	  },
83	
84	  async findRun(workflow, sinceMs) {
85	    const d = await this.api(`/repos/${this.repo}/actions/runs?event=repository_dispatch&per_page=10`);
86	    return (d?.workflow_runs || []).find(
87	      (r) => r.path?.endsWith(`/${workflow}.yml`) && Date.parse(r.created_at) >= sinceMs - 15000,
88	    ) || null;
89	  },
90	};
91	
92	/* ══════════════════════════════════════════════════════════════════════
93	   The brief — one state object behind both the chat and the form.
94	   Every slot knows who set it: "you", "devin", or "assumed".
95	   ══════════════════════════════════════════════════════════════════════ */
96	
97	const ROOM_LABELS = {
98	  bedroom: "Bedroom", living: "Living room", kitchen: "Kitchen",
99	  bathroom: "Bathroom", office: "Workspace", meeting: "Meeting room",
100	  lab: "Workshop", utility: "Utility", hall: "Hall", other: "Room",
101	};
102	const CLASS_LABELS = {
103	  detached_house: "A detached house", semi_detached: "A semi-detached house",
104	  apartment_block: "An apartment building", workplace: "A workplace",
105	  coworking_space: "A co-working space", office_building: "An office building",
106	  practice: "A practice", studio_building: "A studio",
107	};
108	const RESIDENTIAL = ["detached_house", "semi_detached", "apartment_block"];
109	const isWorkspace = () => !RESIDENTIAL.includes(Brief.f.building_class);
110	const classLabel = (c) => CLASS_LABELS[c] || ("A " + String(c).replaceAll("_", " "));
111	
112	const Brief = {
113	  f: {},          // fields
114	  src: {},        // slot -> you | devin | assumed
115	  reset() {
