1	/* Recognition — an AI architect you talk to.
2	 *
3	 * The flow: describe the building in your own words → the agent asks only
4	 * what it genuinely needs (fitted to the building type) → four structurally
5	 * different blueprints arrive as options → refine in words, redraft → pick
6	 * one → the 3D model. Regulations run underneath as the quality gate; the
7	 * conversation never lectures about them, and the checks are always one tap
8	 * away — counted honestly, cited fully.
9	 *
10	 * The page is static and holds no secret. Live work runs through GitHub
11	 * Actions: with the viewer's token it dispatches directly; without one it
12	 * hands over the exact trigger command and live-follows the run. Every agent
13	 * reply is labelled with the engine that produced it, and every inferred
14	 * value is a visible assumption. No step ticks without a real event.
15	 */
16	import * as THREE from "three";
17	import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/controls/OrbitControls.js";
18	
19	const $ = (id) => document.getElementById(id);
20	const el = (tag, cls, text) => {
21	  const n = document.createElement(tag);
22	  if (cls) n.className = cls;
23	  if (text != null) n.textContent = text;
24	  return n;
25	};
26	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
27	const REDUCED = matchMedia("(prefers-reduced-motion: reduce)").matches;
28	
29	/* ══════════════════════════════════════════════════════════════════════
30	   GitHub — the viewer's own credentials, api.github.com only.
31	   Public reads need no credential at all; only triggering does.
32	   ══════════════════════════════════════════════════════════════════════ */
33	
34	function detectRepo() {
35	  const host = location.hostname;
36	  if (host.endsWith(".github.io")) {
37	    const owner = host.split(".")[0];
38	    const seg = location.pathname.split("/").filter(Boolean)[0];
39	    if (owner && seg) return `${owner}/${seg}`;
40	  }
41	  return "0-uddeshya-0/Recognition";
42	}
43	
44	const GH = {
45	  repo: detectRepo(),
46	  get token() { return localStorage.getItem("recognition.gh_token") || ""; },
47	  set token(v) { v ? localStorage.setItem("recognition.gh_token", v) : localStorage.removeItem("recognition.gh_token"); },
48	  get on() { return !!this.token; },
49	  get pollMs() { return this.token ? 6000 : 12000; },
50	
51	  async api(path, opts = {}) {
52	    const headers = {
53	      Accept: "application/vnd.github+json",
54	      "X-GitHub-Api-Version": "2022-11-28",
55	      ...(opts.headers || {}),
56	    };
57	    if (this.token) headers.Authorization = `Bearer ${this.token}`;
58	    const r = await fetch(`https://api.github.com${path}`, { ...opts, headers });
59	    if (r.status === 404) return null;
60	    if (!r.ok) throw new Error(`GitHub ${r.status}: ${(await r.text()).slice(0, 140)}`);
61	    return r.status === 204 ? true : r.json();
62	  },
63	
64	  dispatch(event_type, client_payload) {
65	    return this.api(`/repos/${this.repo}/dispatches`, {
66	      method: "POST",
67	      body: JSON.stringify({ event_type, client_payload }),
68	    });
69	  },
70	
71	  async raw(path, ref) {
72	    if (!this.token) {
73	      const r = await fetch(
74	        `https://raw.githubusercontent.com/${this.repo}/${ref}/${path}?t=${Date.now()}`,
75	        { cache: "no-store" },
76	      );
77	      return r.ok ? r.json().catch(() => null) : null;
78	    }
79	    const r = await fetch(
80	      `https://api.github.com/repos/${this.repo}/contents/${path}?ref=${ref}&t=${Date.now()}`,
81	      { headers: { Accept: "application/vnd.github.raw+json", Authorization: `Bearer ${this.token}` } },
82	    );
83	    return r.ok ? r.json() : null;
84	  },
85	
86	  async findRun(workflow, sinceMs) {
87	    const d = await this.api(`/repos/${this.repo}/actions/runs?per_page=12`);
88	    return (d?.workflow_runs || []).find(
89	      (r) => r.path?.endsWith(`/${workflow}.yml`) && Date.parse(r.created_at) >= sinceMs - 20000,
90	    ) || null;
91	  },
92	};
93	
94	function b64(s) { return btoa(String.fromCharCode(...new TextEncoder().encode(s))); }
95	function triggerCommand(workflow, field, payload, extra = "") {
96	  return `gh workflow run ${workflow} --repo ${GH.repo} --ref main${extra} -f ${field}="$(echo ${b64(JSON.stringify(payload))} | base64 -d)"`;
97	}
98	
99	/* ══════════════════════════════════════════════════════════════════════
100	   The brief — one state object. Every slot knows who set it.
101	   ══════════════════════════════════════════════════════════════════════ */
102	
103	const ROOM_LABELS = {
104	  bedroom: "Bedroom", living: "Living room", kitchen: "Kitchen",
105	  bathroom: "Bathroom", office: "Workspace", meeting: "Meeting room",
106	  lab: "Hall floor", utility: "Utility", hall: "Hallway", other: "Room",
107	};
108	const CLASS_LABELS = {
109	  detached_house: "A detached house", semi_detached: "A semi-detached house",
110	  apartment_block: "An apartment building", apartment: "An apartment",
111	  workplace: "A workplace", coworking_space: "A co-working space",
112	  office_building: "An office", practice: "A practice",
113	  studio_building: "A studio", warehouse: "A warehouse",
114	};
115	const RESIDENTIAL = ["detached_house", "semi_detached", "apartment_block", "apartment"];
116	const isWorkspace = () => !RESIDENTIAL.includes(Brief.f.building_class);
117	const classLabel = (c) => CLASS_LABELS[c] || ("A " + String(c).replaceAll("_", " "));
118	
119	const Brief = {
120	  f: {}, src: {},
121	  reset() {
122	    this.f = {
123	      project: "Neubau", bundesland: "BY", building_class: "detached_house",
124	      plot_width_m: 18, plot_depth_m: 24, dwelling_count: null, storey_count: 1,
125	      storey_height_m: 2.5, occupants: null, rooms: {}, roomAreas: {},
126	      accessibility_tier: "none", notes: "",
127	    };
128	    this.src = {};
129	    renderSpecs();
130	  },
131	  set(slot, value, by) { this.f[slot] = value; this.src[slot] = by; renderSpecs(); },
132	  addRooms(patch, by) {
133	    for (const [cat, n] of Object.entries(patch)) {
134	      if (n > 0) this.f.rooms[cat] = n; else { delete this.f.rooms[cat]; delete this.f.roomAreas[cat]; }
135	    }
136	    if (Object.keys(patch).length) this.src.rooms = by;
137	    renderSpecs();
138	  },
139	  get ready() { return Object.keys(this.f.rooms).length > 0; },
140	  seal() {
141	    const assumptions = [];
142	    const f = this.f;
143	    const rooms = { ...f.rooms };
144	    const work = isWorkspace();
145	    for (const [cat, basis] of [
146	      ["kitchen", "every dwelling needs a kitchen — added quietly"],
147	      ["bathroom", "every dwelling needs a bathroom — added quietly"],
148	    ]) {
149	      if (!rooms[cat]) { rooms[cat] = 1; assumptions.push({ slot: `rooms.${cat}`, value: 1, basis, confidence: "high", confirmed: false }); }
150	    }
151	    if (f.dwelling_count == null) {
152	      assumptions.push({
153	        slot: "dwelling_count", value: 1,
154	        basis: work ? "a workplace is one unit" : "described as a single home",
155	        confidence: "high", confirmed: false,
156	      });
157	    }
158	    const occupants = f.occupants || (work ? 8 : 4);
159	    if (f.occupants == null) {
160	      assumptions.push({ slot: "occupants", value: occupants, basis: work ? "typical small team" : "typical household", confidence: "low", confirmed: false });
161	    }
162	    if (!this.src.plot_width_m) {
163	      assumptions.push({ slot: "plot", value: `${f.plot_width_m} × ${f.plot_depth_m} m`, basis: "default plot — say yours anytime", confidence: "low", confirmed: false });
164	    }
165	    for (const [slot, value, basis] of [
166	      ["storey_height_m", 2.5, "standard ceiling: legal minimum 2.40 m plus build-up"],
167	      ["storey_count", 1, "v1 designs a single storey"],
168	    ]) {
169	      if (!this.src[slot]) assumptions.push({ slot, value, basis, confidence: "high", confirmed: false });
170	    }
171	    return {
172	      project: f.project, bundesland: "BY", building_class: f.building_class,
173	      plot_width_m: f.plot_width_m, plot_depth_m: f.plot_depth_m,
174	      dwelling_count: f.dwelling_count ?? 1, storey_count: 1,
175	      storey_height_m: f.storey_height_m, occupants,
176	      rooms: Object.entries(rooms).map(([category, count]) => ({
177	        category, count, min_area_m2: f.roomAreas[category] ?? null, label: null,
178	      })),
179	      accessibility_tier: f.accessibility_tier, assumptions,
180	      notes: f.notes.trim().slice(0, 2000), schema: "designbrief/v1",
181	    };
182	  },
183	};
184	
185	/* ══════════════════════════════════════════════════════════════════════
186	   Understanding words — deterministic; shows what it got, admits what not.
187	   ══════════════════════════════════════════════════════════════════════ */
188	
189	const NUM_WORDS = {
190	  a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6,
191	  seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12,
192	  ein: 1, eine: 1, einem: 1, zwei: 2, drei: 3, vier: 4, "fünf": 5, fuenf: 5, sechs: 6,
193	  sieben: 7, acht: 8, neun: 9, zehn: 10, "zwölf": 12, zwoelf: 12,
194	};
195	const CAT_WORDS = [
196	  [/bed\s?rooms?|schlafzimmer|kinderzimmer|kids?['’]?\s?rooms?|children'?s rooms?|guest\s?rooms?|g[äa]stezimmer/, "bedroom"],
197	  [/bath\s?rooms?|wash\s?rooms?|rest\s?rooms?|bäder|b[äa]dezimmer|\bbad\b|\bwc\b|toilets?|shower rooms?|duschbad/, "bathroom"],
198	  [/kitchens?|kitchenettes?|küchen?|kueche|teek[üu]che|break rooms?|canteen|cafeteria|pantry/, "kitchen"],
199	  [/living\s?rooms?|lounge|wohnzimmer|wohnbereich/, "living"],
200	  [/conference rooms?|meeting rooms?|boardrooms?|besprechungsr[äa]ume?|konferenzr[äa]ume?/, "meeting"],
201	  [/warehouse floor|storage hall|lagerhalle|workshops?|werkst[äa]tt(?:en)?|maker\s?space|labs?\b|labor/, "lab"],
202	  [/stud(?:y|ies)|studios?|offices?|open.?space|workspaces?|home\s?office|büros?|buero|arbeitszimmer/, "office"],
203	  [/receptions?|lobb(?:y|ies)|foyer|empfang/, "hall"],
204	  [/utilit(?:y|ies)|laundry|hwr|hauswirtschaftsraum|storage rooms?|abstellraum|server rooms?/, "utility"],
205	];
206	const WORK_CLASSES = [
207	  // order matters: the phrase that gets stripped should be the building
208	  // mention, so "an office for my startup" is caught by the office pattern
209	  // (stripping "an office") before the bare "startup" pattern can win.
210	  [/warehouse|lagerhalle|\blager\b/, "warehouse"],
211	  [/co.?working/, "coworking_space"],
212	  [/office building|offices? for|an office\b|my office\b|büro(?:geb[äa]ude|fl[äa]che)/, "office_building"],
213	  [/startup|small (company|business|firm)|our (team|company)\b/, "office_building"],
214	  [/practice|praxis|kanzlei|clinic|klinik/, "practice"],
215	  [/agency|agentur|design studio|studio for|atelier/, "studio_building"],
216	];
217	
218	function wordNum(s) {
219	  const n = parseInt(s, 10);
220	  return Number.isNaN(n) ? (NUM_WORDS[s?.toLowerCase()] ?? null) : n;
221	}
222	
223	function parseUtterance(text) {
224	  let t = " " + text.toLowerCase() + " ";
225	  const got = [];
226	  const rooms = {};
227	  const roomAreas = {};
228	
229	  // The building itself is not a room: detect the class first and blank the
230	  // phrase, so "an office for my startup" doesn't also count an office room.
231	  let workClass = null;
232	  for (const [pat, cls] of WORK_CLASSES) {
233	    const m = t.match(pat);
234	    if (m) { workClass = cls; t = t.replace(m[0], " "); break; }
235	  }
236	
237	  // "3 BHK" — bedrooms + hall(living) + kitchen, said the way people say it
238	  const bhk = t.match(/(\d)\s*bhk/);
239	  if (bhk) {
240	    rooms.bedroom = Math.min(+bhk[1], 6);
241	    rooms.living = 1; rooms.kitchen = 1; rooms.bathroom = Math.max(rooms.bathroom || 0, 1);
242	    got.push([`${bhk[1]} BHK`, "bedrooms + hall + kitchen"]);
243	  }
244	
245	  const numPat = "(\\d+|one|two|three|four|five|six|seven|eight|nine|ten|a|an|ein|eine|zwei|drei|vier|fünf|fuenf|sechs)";
246	  for (const [pat, cat] of CAT_WORDS) {
247	    const re = new RegExp(`${numPat}\\s+(?:${pat.source})|(?:${pat.source})`, "gi");
248	    let m, count = 0, seen = false;
249	    while ((m = re.exec(t)) !== null) {
250	      seen = true;
251	      count += m[1] ? (wordNum(m[1]) ?? 1) : 1;
252	      if (!m[1]) count = Math.max(count, 1);
253	    }
254	    if (seen) rooms[cat] = Math.min(Math.max(rooms[cat] || 0, count), 6);
255	  }
256	  for (const [cat, n] of Object.entries(rooms)) {
257	    if (!bhk || !["bedroom", "living", "kitchen"].includes(cat) || rooms[cat] > (cat === "bedroom" ? +bhk[1] : 1)) {
258	      if (!bhk) got.push([ROOM_LABELS[cat].toLowerCase(), `× ${n}`]);
259	    }
260	  }
261	  if (bhk) for (const cat of Object.keys(rooms)) {
262	    if (!["bedroom", "living", "kitchen", "bathroom"].includes(cat)) got.push([ROOM_LABELS[cat].toLowerCase(), `× ${rooms[cat]}`]);
263	  }
264	
265	  const patch = {};
266	
267	  const dw = t.match(new RegExp(`${numPat}\\s+(?:famil(?:y|ies|ien)|homes?|households?|apartments?|flats?|units?|wohnungen|wohneinheiten|parteien)`));
268	  if (dw && wordNum(dw[1]) > 1) patch.dwelling_count = wordNum(dw[1]);
269	  else if (/dreifamilien|three.?family/.test(t)) patch.dwelling_count = 3;
270	  else if (/zweifamilien|two.?family|duplex|doppelhaus/.test(t)) patch.dwelling_count = 2;
271	  else if (/einfamilien|single.?family|just (us|our family)|nur wir/.test(t)) patch.dwelling_count = 1;
272	  if (patch.dwelling_count) got.push(["homes", String(patch.dwelling_count)]);
273	
274	  if (workClass) patch.building_class = workClass;
275	  else if (/apartment (building|block|complex)|mehrfamilienhaus|wohnblock/.test(t)) patch.building_class = "apartment_block";
276	  else if (/\b(an?|my|our|the)\s+(apartment|flat|wohnung)\b|\d\s*bhk/.test(t)) patch.building_class = "apartment";
277	  else if (/semi.?detached|doppelhaush[äa]lfte/.test(t)) patch.building_class = "semi_detached";
278	  else if (/detached|house|home\b|haus\b|cottage|weekend house|ferienhaus|bungalow|villa/.test(t)) patch.building_class = "detached_house";
279	  if (patch.building_class) got.push(["building", classLabel(patch.building_class).toLowerCase()]);
280	
281	  // a warehouse IS its floor — make sure the floor itself is in the programme
282	  if (patch.building_class === "warehouse" && !rooms.lab) { rooms.lab = 1; }
283	
284	  const plot = t.match(/(\d{1,3})\s*(?:x|×|by|mal)\s*(\d{1,3})\s*(?:m\b|met)/);
285	  if (plot) {
286	    patch.plot_width_m = +plot[1]; patch.plot_depth_m = +plot[2];
287	    got.push(["plot", `${plot[1]} × ${plot[2]} m`]);
288	  }
289	
290	  // a bare floor area — for warehouses and big rooms: "about 300 m² of floor"
291	  const floor = t.match(/(\d{2,5})\s*(?:m2|m²|sqm|square met|quadratmet)/);
292	  if (floor && (workClass === "warehouse" || Chat.awaitingFloor)) {
293	    roomAreas.lab = Math.min(+floor[1], 2000);
294	    rooms.lab = rooms.lab || 1;
295	    got.push(["floor", `${floor[1]} m²`]);
296	  }
297	
298	  const occNum = "(\\d+|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|zwei|drei|vier|fünf|fuenf|sechs|sieben|acht|neun|zehn|zwölf|zwoelf)";
299	  const occ = t.match(new RegExp(`(?:family|team|group) of ${occNum}|${occNum}\\s+(?:of us|people|persons?|personen|employees?|mitarbeiter|desks?|seats?|arbeitspl[äa]tze)|zu\\s+(dritt|viert|fünft|sechst)`));
300	  if (occ) {
301	    const zu = { dritt: 3, viert: 4, "fünft": 5, sechst: 6 };
302	    patch.occupants = occ[3] ? zu[occ[3]] : wordNum(occ[1] || occ[2]);
303	    if (patch.occupants) got.push(["people", `${patch.occupants}`]);
304	  }
305	
306	  if (/wheelchair|rollstuhl/.test(t)) patch.accessibility_tier = "din18040_2_R";
307	  else if (/barrier.?free|barrierefrei|accessible|step.?free|altersgerecht/.test(t)) patch.accessibility_tier = "din18040_2";
308	  if (patch.accessibility_tier) got.push(["barrier-free", "yes"]);
309	
310	  const st = t.match(new RegExp(`${numPat}\\s+(?:store(?:y|ys|ies)|floors?|geschoss(?:e|ig)?|stockwerke?|etagen)`));
311	  const storeysAsked = st ? wordNum(st[1]) : (/zweigeschossig|two.?stor(?:e?y|ies)/.test(t) ? 2 : null);
312	
313	  const name = text.match(/(?:for the|für(?: die)?(?: Familie)?|for)\s+([A-ZÄÖÜ][a-zA-Zäöüß]+)(?:\s+family|\s+familie)?/);
314	  if (name && /family|familie|Familie/.test(text)) {
315	    patch.project = `Haus ${name[1]}`;
316	    got.push(["project", patch.project]);
317	  }
318	
319	  const multiHint = /apartment (building|block|complex)|mehrfamilien|several (families|units)|wohnblock/.test(t);
320	  return { patch, rooms, roomAreas, got, storeysAsked, multiHint };
321	}
322	
323	/* ══════════════════════════════════════════════════════════════════════
324	   The conversation
325	   ══════════════════════════════════════════════════════════════════════ */
326	
327	const Chat = {
328	  transcript: [], id: null, round: 0, session: "", waiting: false,
329	  askedRooms: false, askedPeople: false, askedDwelling: false, askedFloor: false,
330	  awaitingFloor: false, proposed: false, multiHint: false,
331	};
332	const Draft = { round: 0, id: null, bundle: null, sealed: null, selected: null, busy: false };
333	
334	function addMsg(who, text, { meta, wait } = {}) {
335	  const li = el("li", `msg ${who}${wait ? " wait" : ""}`);
336	  li.append(el("div", "bubble", text));
337	  if (meta) { const m = el("div", "meta"); m.append(meta); li.append(m); }
338	  $("chat-log").append(li);
339	  $("chat-log").scrollTop = $("chat-log").scrollHeight;
340	  return li;
341	}
342	
343	function agentSay(text, { chips = [], devin = false, sessionUrl = "" } = {}) {
344	  const meta = el("span");
345	  if (devin) {
346	    meta.append("Devin · live session");
347	    if (sessionUrl) {
348	      meta.append(" · ");
349	      const a = el("a", null, "watch ↗");
