381	  copy.onclick = async () => {
382	    try { await navigator.clipboard.writeText(cmd); copy.textContent = "Copied ✓"; }
383	    catch { copy.textContent = "Select + copy"; }
384	    setTimeout(() => { copy.textContent = "Copy"; }, 2500);
385	  };
386	  box.append(pre, copy);
387	  li.append(box);
388	  li.append(el("div", "meta", "tokenless trigger · this page holds no secret"));
389	  $("chat-log").scrollTop = $("chat-log").scrollHeight;
390	  return li;
391	}
392	
393	function applyParsed(parsed, by) {
394	  Brief.addRooms(parsed.rooms, by);
395	  for (const [cat, a] of Object.entries(parsed.roomAreas)) Brief.f.roomAreas[cat] = a;
396	  for (const [k, v] of Object.entries(parsed.patch)) Brief.set(k, v, by);
397	  if (parsed.multiHint) Chat.multiHint = true;
398	}
399	
400	/* The instant agent — asks only what it can't infer, fitted to the type. */
401	function instantNext(parsed) {
402	  const f = Brief.f;
403	  const work = isWorkspace();
404	  const wh = f.building_class === "warehouse";
405	
406	  if (parsed?.storeysAsked > 1) {
407	    agentSay(`Noted — ${parsed.storeysAsked} storeys. I design a single storey for now, so I'll plan the ground floor beautifully and keep the wish on file.`);
408	    Brief.set("notes", (f.notes + ` Client wants ${parsed.storeysAsked} storeys (v1 designs one).`).trim(), "you");
409	  }
410	
411	  if (Chat.multiHint && f.dwelling_count == null && !Chat.askedDwelling) {
412	    Chat.askedDwelling = true;
413	    agentSay("How many homes should the building hold?",
414	      { chips: [{ label: "Two", send: "Two homes" }, { label: "Three", send: "Three homes" }, { label: "Four", send: "Four homes" }] });
415	    return;
416	  }
417	
418	  if (wh && !f.roomAreas.lab && !Chat.askedFloor) {
419	    Chat.askedFloor = true;
420	    Chat.awaitingFloor = true;
421	    agentSay("Roughly how much hall floor do you need? I'll add a small office corner and a washroom alongside.",
422	      { chips: [{ label: "100 m²", send: "About 100 m² of floor" }, { label: "200 m²", send: "About 200 m² of floor" }, { label: "400 m²", send: "About 400 m² of floor" }] });
423	    return;
424	  }
425	
426	  if (work && !wh && f.occupants == null && !Chat.askedPeople) {
427	    Chat.askedPeople = true;
428	    agentSay("How many people will work there day to day? That's what sizes the space.",
429	      { chips: [{ label: "5 of us", send: "5 people" }, { label: "10", send: "10 people" }, { label: "About 20", send: "20 people" }] });
430	    return;
431	  }
432	
433	  if (!Brief.ready && !Chat.askedRooms) {
434	    Chat.askedRooms = true;
435	    agentSay(
436	      work
437	        ? "Tell me the spaces you need — in your own words. \"An open studio, a meeting room, a small kitchen\" is plenty."
438	        : "Which rooms should it have? Say it however you'd say it — \"three bedrooms, a study, an open kitchen\" works.",
439	      { chips: [] },
440	    );
441	    return;
442	  }
443	  if (!Brief.ready) return;
444	
445	  if (!Chat.proposed) {
446	    Chat.proposed = true;
447	    Chat.awaitingFloor = false;
448	    const what = classLabel(f.building_class).toLowerCase();
449	    agentSay(
450	      `Lovely — I have what I need for ${what}. I'll draft four structurally different blueprints, dimensioned and checked; it takes about two minutes. Anything else first?`,
451	      { chips: [
452	        { label: "Draft the blueprints", action: () => draftRound() },
453	        { label: "One more thing…", action: () => { setChips([]); $("chat-input").focus(); } },
454	      ] },
455	    );
456	    return;
457	  }
458	
459	  // options already exist (or were proposed): any new understanding redrafts
460	  if (Draft.bundle || Draft.busy) return;
461	  agentSay("Got it. Ready when you are —",
462	    { chips: [{ label: "Draft the blueprints", action: () => draftRound() }] });
463	}
464	
465	async function submitUtterance(text) {
466	  text = text.trim();
467	  if (!text || Chat.waiting || Draft.busy) return;
468	  addMsg("you", text);
469	  Chat.transcript.push({ role: "client", text });
470	  $("chat-input").value = "";
471	  autoGrow();
472	
473	  const parsed = parseUtterance(text);
474	  applyParsed(parsed, "you");
475	  Brief.set("notes", (Brief.f.notes + " " + text).trim().slice(0, 2000), Brief.src.notes || "you");
476	
477	  if ($("chat-engine").value === "devin") return devinRound();
478	
479	  if (parsed.got.length) {
480	    const li = $("chat-log").lastElementChild;
481	    const row = el("div", "got");
482	    parsed.got.forEach(([k, v]) => {
483	      const c = el("span", "chip");
484	      c.append(el("span", null, k + " "), el("b", null, v));
485	      row.append(c);
486	    });
487	    li.append(row);
488	    li.scrollIntoView({ block: "end" });
489	  } else if (text.split(/\s+/).length > 6) {
490	    agentSay(
491	      "I read that, but I couldn't pull anything concrete from it — I'm the instant engine and my vocabulary is rooms and sizes. Rephrase, or hand the conversation to Devin, which genuinely reads.",
492	      { chips: [
493	        { label: "Hand it to Devin", action: () => { $("chat-engine").value = "devin"; devinRound(); } },
494	        { label: "I'll rephrase", action: () => { setChips([]); $("chat-input").focus(); } },
495	      ] },
496	    );
497	    return;
498	  }
499	
500	  // refining after options exist → redraft with the change
501	  if (Draft.bundle && parsed.got.length) {
502	    agentSay(`Changing that — I'll redraft the four takes. Two minutes.`);
503	    return draftRound();
504	  }
505	  instantNext(parsed);
506	}
507	
508	/* --- Devin: one relay round = one live turn ----------------------------- */
509	
510	async function devinRound() {
511	  Chat.id = Chat.id || (crypto.randomUUID ? crypto.randomUUID() : String(Date.now())).replace(/[^a-zA-Z0-9-]/g, "").slice(0, 40);
512	  Chat.round += 1;
513	  Chat.waiting = true;
514	  $("chat-send").dataset.state = "busy";
515	  $("chat-engine").disabled = true;
516	
517	  const payload = {
518	    id: Chat.id, round: Chat.round, session_id: Chat.session,
519	    messages: Chat.transcript.slice(-30).map((m) => ({ role: m.role, text: m.text.slice(0, 2000) })),
520	    known: Brief.f,
521	  };
522	
523	  const t0 = Date.now();
524	  if (!GH.on) {
525	    commandBubble(
526	      "This page holds no secret, so it can't start the session itself. Run this in any terminal with gh — I'm already watching for Devin's reply:",
527	      triggerCommand("interview.yml", "payload", payload),
528	    );
529	  } else {
530	    try {
531	      await GH.dispatch("interview", payload);
532	    } catch (e) {
533	      endWait();
534	      agentSay(`Couldn't start the round: ${e.message}.`);
535	      return;
536	    }
537	  }
538	
539	  const wait = addMsg("agent",
540	    GH.on ? "Devin is reading the conversation… first reply usually takes 2–4 minutes."
541	          : "Waiting for the trigger… once it runs, Devin's reply lands here (tokenless reads lag up to a minute).",
542	    { wait: true });
543	  const meta = el("div", "meta");
544	  wait.append(meta);
545	  const tick = setInterval(() => {
546	    meta.textContent = `waiting ${Math.round((Date.now() - t0) / 1000)}s · relayed through Actions`;
547	  }, 1000);
548	  setChips([{ label: "Stop waiting", action: () => { cancel.hit = true; } }]);
549	  const cancel = { hit: false };
550	
551	  GH.findRun("interview", t0).then((r) => {
552	    if (r) {
553	      meta.append(" · ");
554	      const a = el("a", null, "run ↗"); a.href = r.html_url; a.target = "_blank"; a.rel = "noopener";
555	      meta.append(a);
556	    }
557	  }).catch(() => {});
558	
559	  const path = `interviews/${Chat.id}/reply-${Chat.round}.json`;
560	  let reply = null;

