1	/* Recognition — glass studio.
2	   The scene is a soft architectural morning; every surface is glass over it.
3	   Rules that hold the look together: text always sits on strong glass (blur +
4	   ≥.55 white) so contrast stays ≥4.5:1; verdict colour appears only on the
5	   code pill and inside the checks drawer; numbers are always monospace. */
6	
7	:root {
8	  --ink: #1b2230;
9	  --ink-2: #4c5568;
10	  --ink-3: #7b8497;
11	  --accent: #3b5bdb;
12	  --accent-deep: #2c46b8;
13	  --pass: #157347;
14	  --fail: #c0392f;
15	  --warn: #b8740a;
16	
17	  --glass: rgba(255, 255, 255, 0.42);
18	  --glass-strong: rgba(255, 255, 255, 0.62);
19	  --glass-soft: rgba(255, 255, 255, 0.28);
20	  --glass-ink: rgba(27, 34, 48, 0.78);
21	  --glass-line: rgba(255, 255, 255, 0.65);
22	  --glass-line-soft: rgba(255, 255, 255, 0.4);
23	  --blur: blur(20px) saturate(1.5);
24	  --shadow: 0 12px 40px rgba(31, 45, 90, 0.14), 0 2px 8px rgba(31, 45, 90, 0.08);
25	  --shadow-soft: 0 6px 24px rgba(31, 45, 90, 0.1);
26	  --r: 20px;
27	  --r-sm: 13px;
28	
29	  --font-display: "Bricolage Grotesque", "Helvetica Neue", sans-serif;
30	  --font-ui: "Sora", "Helvetica Neue", system-ui, sans-serif;
31	  --font-mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
32	}
33	
34	* { box-sizing: border-box; }
35	html, body { margin: 0; height: 100%; }
36	body {
37	  font-family: var(--font-ui); font-size: 14.5px; line-height: 1.55; color: var(--ink);
38	  overflow: hidden;
39	  -webkit-font-smoothing: antialiased;
40	}
41	a { color: var(--accent); text-decoration: none; }
42	a:hover { text-decoration: underline; }
43	button { font: inherit; color: inherit; cursor: pointer; }
44	.mono, code, pre { font-family: var(--font-mono); }
45	.mini { font-size: 12px; color: var(--ink-3); }
46	.hide { display: none !important; }
47	:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }
48	@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } }
49	
50	/* ---- the scene ---------------------------------------------------------- */
51	.bg { position: fixed; inset: 0; z-index: -2; background:
52	  linear-gradient(158deg, #e9effc 0%, #e4e9f8 34%, #f4ecdf 78%, #f7f0e4 100%); }
53	.bg::before {
54	  content: ""; position: absolute; inset: -20%;
55	  background:
56	    radial-gradient(38% 46% at 22% 24%, rgba(87, 116, 226, 0.20), transparent 70%),
57	    radial-gradient(30% 38% at 78% 18%, rgba(203, 156, 87, 0.16), transparent 70%),
58	    radial-gradient(42% 50% at 74% 82%, rgba(87, 150, 226, 0.13), transparent 70%);
59	  filter: blur(40px);
60	}
61	.bg::after {
62	  content: ""; position: absolute; inset: 0; opacity: 0.5;
63	  background:
64	    repeating-linear-gradient(0deg, rgba(59, 91, 219, 0.045) 0 1px, transparent 1px 44px),
65	    repeating-linear-gradient(90deg, rgba(59, 91, 219, 0.045) 0 1px, transparent 1px 44px);
66	  mask-image: radial-gradient(90% 90% at 50% 40%, #000 30%, transparent 100%);
67	}
68	
69	/* ---- glass primitives --------------------------------------------------- */
70	.glass {
71	  background: var(--glass);
72	  -webkit-backdrop-filter: var(--blur); backdrop-filter: var(--blur);
73	  border: 1px solid var(--glass-line);
74	  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.75);
75	  border-radius: var(--r);
76	}
77	.pill, .glass-pill {
78	  display: inline-flex; align-items: center; gap: 7px;
79	  background: var(--glass-strong);
80	  -webkit-backdrop-filter: var(--blur); backdrop-filter: var(--blur);
81	  border: 1px solid var(--glass-line);
82	  box-shadow: var(--shadow-soft), inset 0 1px 0 rgba(255, 255, 255, 0.8);
83	  border-radius: 999px; padding: 9px 16px; font-size: 13.5px; font-weight: 500;
84	  transition: transform 0.18s ease-out, box-shadow 0.18s ease-out, background 0.18s;
85	}
86	.pill:hover, .glass-pill:hover { transform: translateY(-1px); background: rgba(255, 255, 255, 0.75); }
87	.pill:active, .glass-pill:active { transform: translateY(0); }
88	.pill:disabled { opacity: 0.5; cursor: default; transform: none; }
89	.pill.sm { padding: 5px 11px; font-size: 12px; }
90	.pill.primary {
91	  background: linear-gradient(140deg, var(--accent), var(--accent-deep));
92	  color: #fff; border-color: rgba(255, 255, 255, 0.35); font-weight: 600;
93	}
94	.pill.primary:hover { background: linear-gradient(140deg, #4463e2, var(--accent-deep)); }
95	.pill.primary[data-state="busy"] { opacity: 0.6; cursor: progress; }
96	
97	/* ---- top bar ------------------------------------------------------------ */
98	.bar {
99	  position: fixed; top: 16px; left: 18px; right: 18px; z-index: 40;
100	  display: flex; align-items: center; gap: 10px; pointer-events: none;
101	}
