112	  position: absolute; right: 0; top: calc(100% + 10px); width: min(350px, calc(100vw - 32px));
113	  background: var(--glass-strong); -webkit-backdrop-filter: var(--blur); backdrop-filter: var(--blur);
114	  border: 1px solid var(--glass-line); border-radius: var(--r-sm);
115	  box-shadow: var(--shadow); padding: 15px 17px; z-index: 60;
116	}
117	.pop h3 { margin: 0 0 5px; font-size: 14px; font-family: var(--font-display); }
118	.pop .mini { margin: 0 0 10px; }
119	.pop input {
120	  width: 100%; font-family: var(--font-mono); font-size: 12.5px; padding: 9px 11px;
121	  border: 1px solid var(--glass-line); border-radius: 9px; background: rgba(255, 255, 255, 0.7);
