/* Recognition — pitch deck generator.
   Brand: cobalt on near-white, ink for type, mono for every number.
   Motif: rounded white cards with a soft shadow + the product's square glyph. */
const pptxgen = require("pptxgenjs");

const INK = "1B2230";
const INK2 = "4C5568";
const MUTED = "7B8497";
const COBALT = "3B5BDB";
const DEEP = "2C46B8";
const LIFT = "8AA4F2";
const PAPER = "FFFFFF";
const MIST = "F4F7FD";
const PASS = "157347";
const FAIL = "C0392F";

const H = "Arial";       // headers — safe, geometric, true-to-width in QA
const B = "Calibri";     // body
const M = "Courier New"; // every number, tag and verdict

const p = new pptxgen();
p.layout = "LAYOUT_WIDE";           // 13.333 x 7.5
p.author = "Recognition";
p.company = "Recognition";
p.title = "Recognition — your AI architect";

const shadow = () => ({ type: "outer", color: "1F2D5A", blur: 14, offset: 3, angle: 90, opacity: 0.13 });

function light(s) { s.background = { color: MIST }; }
function dark(s) { s.background = { color: INK }; }

// the product's mark: a rounded outline square with a cobalt square inside
function glyph(s, x, y, size, ring) {
  s.addShape(p.ShapeType.roundRect, {
    x, y, w: size, h: size, rectRadius: size * 0.26,
    fill: { color: "FFFFFF", transparency: 100 },
    line: { color: ring, width: 1.75 },
  });
  s.addShape(p.ShapeType.rect, {
    x: x + size * 0.28, y: y + size * 0.28, w: size * 0.44, h: size * 0.44,
    fill: { color: COBALT }, line: { color: COBALT, width: 0 },
  });
}

function title(s, text, opts = {}) {
  s.addText(text, {
    x: 0.62, y: opts.y ?? 0.52, w: 12.1, h: 0.9, margin: 0,
    fontFace: H, fontSize: opts.size ?? 34, bold: true,
    color: opts.color ?? INK, align: "left", valign: "middle",
  });
}

function kicker(s, text, color = COBALT) {
  s.addText(text.toUpperCase(), {
    x: 0.64, y: 0.24, w: 12, h: 0.3, margin: 0,
    fontFace: M, fontSize: 10.5, bold: true, charSpacing: 2, color, valign: "middle",
  });
}

function card(s, x, y, w, h, fill = PAPER) {
  s.addShape(p.ShapeType.roundRect, {
    x, y, w, h, rectRadius: 0.14,
    fill: { color: fill }, line: { color: "E3E9F5", width: 0.75 }, shadow: shadow(),
  });
}

/* ─────────────────────────────── 1 · title ─────────────────────────────── */
{
  const s = p.addSlide(); dark(s);
  glyph(s, 0.75, 0.72, 0.46, "FFFFFF");
  s.addText("Recognition", {
    x: 0.72, y: 1.55, w: 8.4, h: 1.15, margin: 0,
    fontFace: H, fontSize: 58, bold: true, color: PAPER, valign: "middle",
  });
  s.addText("your AI architect", {
    x: 0.78, y: 2.62, w: 8, h: 0.5, margin: 0,
    fontFace: H, fontSize: 25, color: LIFT, valign: "middle",
  });
  s.addText(
    "Describe a building in plain words. Get four verified blueprints, a 3D model, " +
    "and files a builder can open — with nobody in the loop between your sentence " +
    "and the artifacts.",
    { x: 0.75, y: 3.45, w: 7.7, h: 1.5, margin: 0, fontFace: B, fontSize: 16.5, color: "C8D2E8", lineSpacing: 26 },
  );
  s.addText("Devin plans it  ·  deterministic code draws it  ·  a cited rule engine verifies it", {
    x: 0.75, y: 5.05, w: 8, h: 0.34, margin: 0, fontFace: B, fontSize: 13.5, color: LIFT,
  });
  s.addShape(p.ShapeType.roundRect, {
    x: 0.75, y: 5.85, w: 5.15, h: 0.62, rectRadius: 0.31,
    fill: { color: COBALT }, line: { color: COBALT, width: 0 },
  });
  s.addText("0-uddeshya-0.github.io/Recognition", {
    x: 0.75, y: 5.85, w: 5.15, h: 0.62, margin: 0,
    fontFace: M, fontSize: 13, bold: true, color: PAPER, align: "center", valign: "middle",
  });
  s.addImage({ path: "glass-hero-375.png", x: 9.55, y: 0.62, w: 3.0, h: 6.26, rounding: false, shadow: shadow() });
  s.addNotes("Recognition is an AI architect. You describe a building in plain words; it returns four verified blueprints, a 3D model, and builder-grade files — no human in the loop.");
}

/* ──────────────────────────── 2 · the problem ──────────────────────────── */
{
  const s = p.addSlide(); light(s);
  kicker(s, "the problem");
  title(s, "Every industry has an engineering problem");

  card(s, 0.62, 1.72, 5.9, 3.25);
  s.addText("SOFTWARE", { x: 0.95, y: 1.98, w: 4, h: 0.32, margin: 0, fontFace: M, fontSize: 11, bold: true, charSpacing: 1.5, color: PASS });
  s.addText("has the loop", { x: 0.95, y: 2.34, w: 5, h: 0.5, margin: 0, fontFace: H, fontSize: 24, bold: true, color: INK });
  s.addText("write → run → test → fix", { x: 0.95, y: 2.95, w: 5.2, h: 0.4, margin: 0, fontFace: M, fontSize: 15, color: COBALT });
  s.addText("Every attempt gets a verdict in seconds, so a wrong answer announces itself — which is exactly why an agent can work unsupervised.",
    { x: 0.95, y: 3.5, w: 5.2, h: 1.2, margin: 0, fontFace: B, fontSize: 14.5, color: INK2, lineSpacing: 22 });

  card(s, 6.82, 1.72, 5.9, 3.25);
  s.addText("ARCHITECTURE", { x: 7.15, y: 1.98, w: 4, h: 0.32, margin: 0, fontFace: M, fontSize: 11, bold: true, charSpacing: 1.5, color: FAIL });
  s.addText("had none", { x: 7.15, y: 2.34, w: 5, h: 0.5, margin: 0, fontFace: H, fontSize: 24, bold: true, color: INK });
  s.addText("draw → submit → wait → find out", { x: 7.15, y: 2.95, w: 5.4, h: 0.4, margin: 0, fontFace: M, fontSize: 15, color: FAIL });
  s.addText("A layout that breaks building code surfaces at permit review or on site — months later. Small practices and their clients wait weeks for a first compliant answer, and every change restarts the wait.",
    { x: 7.15, y: 3.5, w: 5.2, h: 1.3, margin: 0, fontFace: B, fontSize: 14.5, color: INK2, lineSpacing: 22 });

  s.addText("Pick a domain with no way to check the work, and an agent is only guessing.", {
    x: 0.62, y: 5.35, w: 12.1, h: 0.6, margin: 0, fontFace: H, fontSize: 19, bold: true, color: INK,
  });
  s.addNotes("Software improves fast because every attempt gets a verdict. Architecture's work goes out and someone finds out months later whether it was right.");
}

/* ──────────────────────────── 3 · the insight ──────────────────────────── */
{
  const s = p.addSlide(); light(s);
  kicker(s, "the insight");
  title(s, "Building code is machine-checkable");

  s.addText(
    "Clear heights. Daylight ratios. Door widths. Corridor clearances. Which rooms a " +
    "dwelling must contain. Every one of them is decidable from a model — an executable " +
    "predicate, not an opinion.",
    { x: 0.62, y: 1.75, w: 6.4, h: 1.6, margin: 0, fontFace: B, fontSize: 16, color: INK2, lineSpacing: 25 },
  );
  s.addText("The verdict already existed.\nNothing was sitting inside the loop.", {
    x: 0.62, y: 3.5, w: 6.3, h: 1.3, margin: 0, fontFace: H, fontSize: 25, bold: true, color: COBALT, lineSpacing: 34,
  });
  s.addText("Recognition is the layer that puts an agent inside it.", {
    x: 0.62, y: 4.95, w: 6.3, h: 0.5, margin: 0, fontFace: B, fontSize: 15.5, color: INK2,
  });

  card(s, 7.35, 1.72, 5.36, 4.35);
  s.addText("THE RULEPACK IN FORCE", { x: 7.68, y: 1.98, w: 4.7, h: 0.3, margin: 0, fontFace: M, fontSize: 10.5, bold: true, charSpacing: 1.5, color: MUTED });
  const rules = [
    ["BayBO Art. 45 (1)", "clear height ≥ 2.40 m", "law"],
    ["BayBO Art. 45 (2)", "glazing ≥ 1/8 of floor", "law"],
    ["BayBO Art. 46", "kitchen + bathroom required", "law"],
    ["BayBO Art. 48 (1)", "> 2 homes → barrier-free", "law"],
    ["DIN 18040-2", "1.20 m clear corridor", "standard"],
    ["Richtwerte", "typical room areas", "guidance"],
  ];
  rules.forEach((r, i) => {
    const y = 2.45 + i * 0.6;
    s.addText(r[0], { x: 7.68, y, w: 2.5, h: 0.3, margin: 0, fontFace: M, fontSize: 11.5, bold: true, color: INK });
    s.addText(r[1], { x: 7.68, y: y + 0.26, w: 3.5, h: 0.28, margin: 0, fontFace: B, fontSize: 12.5, color: INK2 });
    s.addText(r[2], {
      x: 11.35, y: y + 0.03, w: 1.05, h: 0.3, margin: 0, fontFace: M, fontSize: 10,
      bold: true, color: r[2] === "law" ? FAIL : r[2] === "standard" ? "B8740A" : COBALT, align: "right",
    });
  });
  s.addNotes("Building code is machine-checkable: heights, daylight, door widths, corridor clearance. The feedback loop already exists — nothing was inside it.");
}

/* ───────────────────────────── 4 · the product ─────────────────────────── */
{
  const s = p.addSlide(); light(s);
  kicker(s, "the product");
  title(s, "Say it. Choose. Build.");

  const steps = [
    ["1", "Say it", "“An office for my startup — 8 of us, an open studio, a meeting room, a small kitchen.” It asks only what it genuinely can't infer."],
    ["2", "Choose", "Four structurally different blueprints come back, dimensioned and already checked. Keep talking and it redrafts."],
    ["3", "Build", "Pick one: the 3D model appears with the plan below it. Archive it and the pipeline verifies, merges itself, and files it."],
  ];
  steps.forEach((st, i) => {
    const y = 1.7 + i * 1.62;
    card(s, 0.62, y, 5.55, 1.42);
    s.addShape(p.ShapeType.roundRect, {
      x: 0.9, y: y + 0.34, w: 0.5, h: 0.5, rectRadius: 0.15,
      fill: { color: COBALT }, line: { color: COBALT, width: 0 },
    });
    s.addText(st[0], { x: 0.9, y: y + 0.34, w: 0.5, h: 0.5, margin: 0, fontFace: H, fontSize: 17, bold: true, color: PAPER, align: "center", valign: "middle" });
    s.addText(st[1], { x: 1.58, y: y + 0.2, w: 4.3, h: 0.36, margin: 0, fontFace: H, fontSize: 17, bold: true, color: INK, valign: "middle" });
    s.addText(st[2], { x: 1.58, y: y + 0.58, w: 4.4, h: 0.75, margin: 0, fontFace: B, fontSize: 12.5, color: INK2, lineSpacing: 17 });
  });
  s.addImage({ path: "deck-hero.png", x: 6.58, y: 1.85, w: 6.15, h: 3.84, shadow: shadow() });
  s.addText("Live, in the browser — nothing to install, no account, no key.", {
    x: 6.58, y: 5.85, w: 6.15, h: 0.35, margin: 0, fontFace: B, fontSize: 13, color: MUTED,
  });
  s.addNotes("Three moves: say it in plain words, choose from four checked blueprints, build the one you like in 3D. Regulations run underneath, not in your face.");
}

/* ──────────────────────────── 5 · four takes ───────────────────────────── */
{
  const s = p.addSlide(); light(s);
  kicker(s, "the drafting round");
  title(s, "Four takes — every one already checked");
  s.addImage({ path: "deck-options.png", x: 0.62, y: 1.62, w: 8.35, h: 5.22, shadow: shadow() });

  const notes = [
    ["Structurally different", "Compact core, linear frontage, open plan, generous — different topologies, not the same plan ±10%."],
    ["Quietly verified", "Each card carries its own check count. Regulations stay underneath; the citations are one tap away."],
    ["Never a bare PASS", "What the model can't see is counted and shown, never silently passed."],
  ];
  notes.forEach((n, i) => {
    const y = 1.72 + i * 1.75;
    card(s, 9.25, y, 3.47, 1.55);
    s.addText(n[0], { x: 9.5, y: y + 0.22, w: 3, h: 0.32, margin: 0, fontFace: H, fontSize: 14.5, bold: true, color: INK });
    s.addText(n[1], { x: 9.5, y: y + 0.6, w: 3.02, h: 0.85, margin: 0, fontFace: B, fontSize: 12, color: INK2, lineSpacing: 16 });
  });
  s.addNotes("One brief, four structurally different layouts, each verified before you ever see it. Every card shows its own check coverage.");
}

/* ───────────────────────────── 6 · the thesis ──────────────────────────── */
{
  const s = p.addSlide(); dark(s);
  kicker(s, "the thesis", LIFT);
  title(s, "The model plans. The code draws.", { color: PAPER });

  const flow = [
    ["Brief", "sealed intent", LIFT],
    ["Devin", "areas + adjacencies\nno coordinates", COBALT],
    ["Translate", "plan → code\n0 tokens", LIFT],
    ["Build", "IFC4 · sheets · 3D", LIFT],
    ["Verify", "the only gate", "5BD69A"],
  ];
  flow.forEach((f, i) => {
    const x = 0.62 + i * 2.55;
    s.addShape(p.ShapeType.roundRect, {
      x, y: 2.15, w: 2.15, h: 1.5, rectRadius: 0.14,
      fill: { color: "27324A" }, line: { color: f[2], width: 1.25 },
    });
    s.addText(f[0], { x, y: 2.34, w: 2.15, h: 0.38, margin: 0, fontFace: H, fontSize: 16, bold: true, color: PAPER, align: "center" });
    s.addText(f[1], { x, y: 2.76, w: 2.15, h: 0.72, margin: 0, fontFace: M, fontSize: 9.5, color: f[2], align: "center", lineSpacing: 13 });
    if (i < flow.length - 1) {
      s.addText("→", { x: x + 2.16, y: 2.15, w: 0.38, h: 1.5, margin: 0, fontFace: H, fontSize: 20, bold: true, color: LIFT, align: "center", valign: "middle" });
    }
  });

  s.addText("A session cannot fake a pass.", {
    x: 0.62, y: 4.25, w: 12.1, h: 0.5, margin: 0, fontFace: H, fontSize: 25, bold: true, color: PAPER,
  });
  s.addText(
    "Devin never emits a coordinate and never states a regulation — it returns a typed plan. " +
    "The IFC model, the drawings and the verdict are produced afterwards by deterministic code " +
    "it never ran, and judged against a cited ruleset it cannot edit. “I fixed it” is not a claim " +
    "the system can accept from a model.",
    { x: 0.62, y: 4.9, w: 12.1, h: 1.5, margin: 0, fontFace: B, fontSize: 15, color: "C8D2E8", lineSpacing: 24 },
  );
  s.addNotes("The whole design is this split: the model plans in relationships and areas; deterministic code turns that into geometry and judges it. That is why the agent can run unsupervised.");
}

/* ──────────────────────────── 7 · Devin at work ────────────────────────── */
{
  const s = p.addSlide(); light(s);
  kicker(s, "where devin does the work");
  title(s, "Four roles, one autonomous loop");

  const roles = [
    ["Interviewer", "Reads the client's own words and returns a typed brief — questions only where a rule genuinely needs one, every inferred value registered as an assumption."],
    ["Architect ×4", "Four sessions in parallel, each handed a structurally different strategy. Each returns an ArchitectPlan: rooms, areas, adjacencies. No coordinates."],
    ["Critic", "Reviews the winner for what a checker cannot see — a room you can't furnish, a route that doesn't work. Advisory by construction; it can annotate, never overturn."],
    ["Repairer", "A contract error goes back verbatim as the repair prompt. Observed live: one rejection, one repair, clean pass — no human saw it."],
  ];
  roles.forEach((r, i) => {
    const x = 0.62 + (i % 2) * 6.2;
    const y = 1.68 + Math.floor(i / 2) * 2.05;
    card(s, x, y, 5.9, 1.85);
    s.addShape(p.ShapeType.roundRect, {
      x: x + 0.3, y: y + 0.28, w: 0.36, h: 0.36, rectRadius: 0.11,
      fill: { color: COBALT }, line: { color: COBALT, width: 0 },
    });
    s.addText(r[0], { x: x + 0.8, y: y + 0.24, w: 4.8, h: 0.42, margin: 0, fontFace: H, fontSize: 17, bold: true, color: INK, valign: "middle" });
    s.addText(r[1], { x: x + 0.32, y: y + 0.78, w: 5.3, h: 0.95, margin: 0, fontFace: B, fontSize: 12.5, color: INK2, lineSpacing: 17 });
  });
  s.addText(
    "Taught by the repo itself: four Agent Skills Devin discovers natively, playbooks per role, " +
    "structured output enforced at the API, and Fusion-shaped delegation — judgement in the main agent, " +
    "mechanical verification to the sidekick.",
    { x: 0.62, y: 5.95, w: 12.1, h: 0.85, margin: 0, fontFace: B, fontSize: 13, color: MUTED, lineSpacing: 18 },
  );
  s.addNotes("Devin is the intelligence in four places: interviewer, four parallel architects, critic, repairer. The repo teaches it with Agent Skills and playbooks.");
}

/* ───────────────────────────── 8 · autonomy ────────────────────────────── */
{
  const s = p.addSlide(); light(s);
  kicker(s, "autonomy — proven, not claimed");
  title(s, "Trigger to merged artifact, nobody in between");

  const stats = [
    ["4", "Devin sessions\nplanning in parallel", COBALT],
    ["2", "rejected by the gate\n— not by a person", FAIL],
    ["1", "pull request opened and\nmerged by github-actions", PASS],
    ["0", "humans in the loop\nafter the trigger", INK],
  ];
  stats.forEach((st, i) => {
    const x = 0.62 + i * 3.11;
    card(s, x, 1.72, 2.85, 2.3);
    s.addText(st[0], { x, y: 1.92, w: 2.85, h: 1.0, margin: 0, fontFace: H, fontSize: 54, bold: true, color: st[2], align: "center", valign: "middle" });
    s.addText(st[1], { x: x + 0.15, y: 2.95, w: 2.55, h: 0.85, margin: 0, fontFace: B, fontSize: 12.5, color: INK2, align: "center", lineSpacing: 17 });
  });

  card(s, 0.62, 4.28, 12.1, 1.95);
  s.addText("THE RUN", { x: 0.95, y: 4.5, w: 3, h: 0.3, margin: 0, fontFace: M, fontSize: 10.5, bold: true, charSpacing: 1.5, color: MUTED });
  s.addText(
    "One workflow_dispatch started four Devin sessions. Each returned a plan; deterministic code " +
    "built and verified all four; the scorer picked the winner; the workflow opened a pull request " +
    "and merged it — then deployed the result to the live site.",
    { x: 0.95, y: 4.86, w: 11.4, h: 0.9, margin: 0, fontFace: B, fontSize: 14, color: INK2, lineSpacing: 21 },
  );
  s.addText("There is no Approve button anywhere in the product.", {
    x: 0.95, y: 5.75, w: 11.4, h: 0.35, margin: 0, fontFace: M, fontSize: 13, bold: true, color: COBALT,
  });
  s.addNotes("A real run: four parallel Devin sessions, the gate rejected two, and the workflow opened and merged the winning design itself. No approve step exists.");
}

/* ──────────────────────────── 9 · verification ─────────────────────────── */
{
  const s = p.addSlide(); light(s);
  kicker(s, "verification");
  title(s, "It knows good from bad — and says what it cannot know");

  card(s, 0.62, 1.7, 6.1, 4.4);
  s.addText("EVERY RULE CARRIES A TIER AND A CITATION", { x: 0.95, y: 1.95, w: 5.5, h: 0.3, margin: 0, fontFace: M, fontSize: 10, bold: true, charSpacing: 1.2, color: MUTED });
  const tiers = [
    ["law", "a cited statute article", "blocks a merge", FAIL],
    ["standard", "a DIN norm, once triggered", "blocks when in force", "B8740A"],
    ["guidance", "published Richtwerte", "never blocks", COBALT],
    ["house", "our own convention", "never blocks", MUTED],
  ];
  tiers.forEach((t, i) => {
    const y = 2.45 + i * 0.78;
    s.addText(t[0], { x: 0.95, y, w: 1.5, h: 0.32, margin: 0, fontFace: M, fontSize: 13, bold: true, color: t[3] });
    s.addText(t[1], { x: 2.5, y, w: 2.9, h: 0.32, margin: 0, fontFace: B, fontSize: 12.5, color: INK2 });
    s.addText(t[2], { x: 0.95, y: y + 0.29, w: 5.2, h: 0.28, margin: 0, fontFace: B, fontSize: 11.5, italic: true, color: MUTED });
  });
  s.addText("A rule without a citation fails to load. No model may author one.", {
    x: 0.95, y: 5.6, w: 5.4, h: 0.35, margin: 0, fontFace: B, fontSize: 12.5, bold: true, color: INK,
  });

  card(s, 7.02, 1.7, 5.7, 2.05);
  s.addText("NO RUN EVER SHOWS A BARE PASS", { x: 7.32, y: 1.94, w: 5, h: 0.3, margin: 0, fontFace: M, fontSize: 10, bold: true, charSpacing: 1.2, color: MUTED });
  s.addText("57 checked · 2 not evaluated · 0 failed", { x: 7.32, y: 2.32, w: 5.1, h: 0.4, margin: 0, fontFace: M, fontSize: 15, bold: true, color: PASS });
  s.addText("Smoke detectors and thresholds cannot be judged from a model, so they are reported — never counted as passes. The coverage travels with every verdict.",
    { x: 7.32, y: 2.8, w: 5.1, h: 0.85, margin: 0, fontFace: B, fontSize: 12, color: INK2, lineSpacing: 16 });

  card(s, 7.02, 3.98, 5.7, 2.12);
  s.addText("THE RULES CONFIGURE THEMSELVES", { x: 7.32, y: 4.22, w: 5, h: 0.3, margin: 0, fontFace: M, fontSize: 10, bold: true, charSpacing: 1.2, color: MUTED });
  s.addText("A brief with three homes auto-triggers BayBO Art. 48: DIN 18040-2 becomes mandatory, and the same 1.15 m corridor finding flips from advisory to blocking. Nobody configured that — the rule declares its own trigger.",
    { x: 7.32, y: 4.58, w: 5.1, h: 1.35, margin: 0, fontFace: B, fontSize: 12.5, color: INK2, lineSpacing: 17 });
  s.addNotes("Tiers and citations decide what may block. Blind spots are declared, never counted as passes. And rules trigger each other: three dwellings make barrier-free mandatory automatically.");
}

/* ──────────────────────────── 10 · artifacts ───────────────────────────── */
{
  const s = p.addSlide(); light(s);
  kicker(s, "artifacts");
  title(s, "Output an architect can actually use");
  s.addImage({ path: "deck-model.png", x: 0.62, y: 1.66, w: 7.4, h: 4.63, shadow: shadow() });

  const arts = [
    ["model.ifc", "IFC4 with real IfcSpace / IfcWall / IfcDoor — opens in Revit or ArchiCAD"],
    ["sheets .dxf", "AIA-named layers, millimetres — straight into AutoCAD"],
    ["sheets .pdf .svg", "dimensioned plans with a title block"],
    ["schedules .csv", "room, door and window schedules"],
    ["verdict.json", "every finding with its tier and statute citation"],
    ["design.py", "the building as readable, diffable code"],
  ];
  arts.forEach((a, i) => {
    const y = 1.72 + i * 0.79;
    s.addText(a[0], { x: 8.3, y, w: 4.4, h: 0.3, margin: 0, fontFace: M, fontSize: 12.5, bold: true, color: COBALT });
    s.addText(a[1], { x: 8.3, y: y + 0.28, w: 4.42, h: 0.44, margin: 0, fontFace: B, fontSize: 12, color: INK2, lineSpacing: 15 });
  });
  s.addNotes("Real deliverables: IFC4 that opens in Revit, DXF for AutoCAD, dimensioned PDFs, CSV schedules, and a verdict citing the statute behind every finding.");
}

/* ───────────────────────────── 11 · closing ────────────────────────────── */
{
  const s = p.addSlide(); dark(s);
  glyph(s, 0.75, 0.7, 0.42, "FFFFFF");
  s.addText("Find an industry.\nGive it an engineer.", {
    x: 0.72, y: 1.4, w: 7.6, h: 1.9, margin: 0, fontFace: H, fontSize: 42, bold: true, color: PAPER, lineSpacing: 50,
  });
  s.addText(
    "Architecture had the loop all along — a machine-checkable verdict nobody had put an agent inside. " +
    "Recognition is that layer, and it runs today: a sentence in, a verified building out.",
    { x: 0.75, y: 3.5, w: 7.5, h: 1.2, margin: 0, fontFace: B, fontSize: 15.5, color: "C8D2E8", lineSpacing: 24 },
  );
  s.addText("Honest limits: v1 designs a single storey, and the cited rulepack is Bayern residential — a workplace is designed gladly and the report says exactly what it could and could not check. A design aid, not a Prüfstatiker.",
    { x: 0.75, y: 4.85, w: 7.5, h: 1.0, margin: 0, fontFace: B, fontSize: 12, italic: true, color: MUTED, lineSpacing: 17 });

  card(s, 8.75, 1.5, 3.95, 4.0, "27324A");
  s.addText("TRY IT", { x: 9.05, y: 1.78, w: 3.4, h: 0.3, margin: 0, fontFace: M, fontSize: 10.5, bold: true, charSpacing: 1.5, color: LIFT });
  s.addText("0-uddeshya-0.github.io\n/Recognition", { x: 9.05, y: 2.12, w: 3.4, h: 0.8, margin: 0, fontFace: M, fontSize: 13, bold: true, color: PAPER, lineSpacing: 19 });
  s.addText("THE CODE", { x: 9.05, y: 3.1, w: 3.4, h: 0.3, margin: 0, fontFace: M, fontSize: 10.5, bold: true, charSpacing: 1.5, color: LIFT });
  s.addText("github.com/0-uddeshya-0\n/Recognition", { x: 9.05, y: 3.44, w: 3.4, h: 0.8, margin: 0, fontFace: M, fontSize: 13, bold: true, color: PAPER, lineSpacing: 19 });
  s.addText("BUILT WITH", { x: 9.05, y: 4.42, w: 3.4, h: 0.3, margin: 0, fontFace: M, fontSize: 10.5, bold: true, charSpacing: 1.5, color: LIFT });
  s.addText("Devin · IfcOpenShell · Python\nThree.js · GitHub Actions", { x: 9.05, y: 4.76, w: 3.4, h: 0.7, margin: 0, fontFace: B, fontSize: 12.5, color: "C8D2E8", lineSpacing: 18 });
  s.addNotes("Architecture had the loop all along. Recognition is the layer that puts an agent inside it — live today, and honest about what it cannot yet do.");
}

p.writeFile({ fileName: "Recognition-pitch.pptx" }).then(() => console.log("written"));

